const RESIDENT_MEMORY_TRIM_TIMER_ID: usize = 0xB470_0509;
const RESIDENT_MEMORY_TRIM_MS: u32 = 25_000;
/// One-shot trim after StackTray opens. The first paint presents the tray, then
