fn next_predicate_kind(current: PredicateKind) -> PredicateKind {
    let all = PredicateKind::ALL;
    let index = all.iter().position(|value| *value == current).unwrap_or(0);
    all[(index + 1) % all.len()]
}

fn next_action_kind(current: ActionKind) -> ActionKind {
    let all = ActionKind::ALL;
    let index = all.iter().position(|value| *value == current).unwrap_or(0);
    all[(index + 1) % all.len()]
}

fn next_run_mode_choice(current: RunModeChoice) -> RunModeChoice {
    let all = RunModeChoice::ALL;
    let index = all.iter().position(|value| *value == current).unwrap_or(0);
    all[(index + 1) % all.len()]
}

