fn handle_settings_passphrase_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> Option<LRESULT> {
    let active = {
        let app = root.app.borrow();
        app.settings_open.get() && app.passphrase_entry_active.get()
    };
    if !active {
        return None;
    }
    match vk {
        VK_BACKSPACE => {
            let app = root.app.borrow();
            let _ = app.passphrase_draft.borrow_mut().pop();
            request_redraw(hwnd);
            Some(0)
        }
        VK_ENTER => {
            let (passphrase, purpose) = {
                let app = root.app.borrow();
                let draft = app.passphrase_draft.borrow().trim().to_owned();
                if draft.is_empty() {
                    app.settings_encryption_status.borrow_mut().replace(
                        SettingsBackupStatus::Error(SmolStr::new_static("Passphrase required")),
                    );
                    request_redraw(hwnd);
                    return Some(0);
                }
                let purpose = app.passphrase_entry_purpose.get();
                app.passphrase_entry_active.set(false);
                app.passphrase_draft.borrow_mut().clear();
                (draft, purpose)
            };
            let command = match purpose {
                PassphraseEntryPurpose::Set => {
                    Command::SetEncryptionPassphrase(SmolStr::new(passphrase))
                }
                PassphraseEntryPurpose::Unlock => {
                    Command::UnlockEncryptionPassphrase(SmolStr::new(passphrase))
                }
            };
            root.dispatcher.push(command);
            request_redraw(hwnd);
            Some(0)
        }
        VK_ESCAPE_KEY => {
            let app = root.app.borrow();
            app.passphrase_entry_active.set(false);
            app.passphrase_draft.borrow_mut().clear();
            app.settings_encryption_status
                .borrow_mut()
                .replace(SettingsBackupStatus::Success(SmolStr::new_static(
                    "Passphrase cancelled",
                )));
            request_redraw(hwnd);
            Some(0)
        }
        _ => None,
    }
}

fn handle_settings_keybinding_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> Option<LRESULT> {
    let (modal_open, recording_action) = {
        let app = root.app.borrow();
        (
            app.settings_open.get() && app.settings_keybindings_open.get(),
            app.settings_keybinding_recording.borrow().clone(),
        )
    };
    if !modal_open {
        return None;
    }
    let Some(action) = recording_action else {
        if vk == VK_ESCAPE_KEY {
            let app = root.app.borrow();
            app.settings_keybindings_open.set(false);
            app.settings_keybinding_recording.borrow_mut().take();
            request_redraw(hwnd);
        }
        return Some(0);
    };
    if vk == VK_ESCAPE_KEY {
        let app = root.app.borrow();
        app.settings_keybinding_recording.borrow_mut().take();
        set_keybinding_feedback(
            &app,
            action.as_str(),
            SmolStr::new_static("Recording cancelled"),
            false,
        );
        request_redraw(hwnd);
        return Some(0);
    }
    let mods = hotkey::ModFlags::from_keystate();
    let Some(chord) = hotkey::format_chord(vk, mods) else {
        return Some(0);
    };
    let app = root.app.borrow();
    app.settings_keybinding_recording.borrow_mut().take();
    if keybindings_section::is_reserved_chord(chord.as_str()) {
        set_keybinding_feedback(
            &app,
            action.as_str(),
            SmolStr::new_static("Reserved by Windows"),
            true,
        );
        request_redraw(hwnd);
        return Some(0);
    }
    match validate_keybinding_candidate(root, action.as_str(), chord.as_str()) {
        Ok(()) => {
            let Some(key) = keybinding_setting_key(action.as_str()) else {
                set_keybinding_feedback(
                    &app,
                    action.as_str(),
                    SmolStr::new_static("Unsupported action"),
                    true,
                );
                request_redraw(hwnd);
                return Some(0);
            };
            set_keybinding_feedback(
                &app,
                action.as_str(),
                SmolStr::new(format!("Saving {chord}")),
                false,
            );
            drop(app);
            root.dispatcher.push(Command::SetSetting {
                key,
                value: bento_nano_app::SettingValue::Str(SmolStr::new(chord)),
            });
        }
        Err(hotkey::BindingValidationError::UnsupportedActionOrChord) => {
            set_keybinding_feedback(
                &app,
                action.as_str(),
                SmolStr::new_static("Unsupported shortcut"),
                true,
            );
        }
        Err(hotkey::BindingValidationError::ChordAlreadyAssigned) => {
            set_keybinding_feedback(
                &app,
                action.as_str(),
                SmolStr::new_static("Already in use"),
                true,
            );
        }
    }
    request_redraw(hwnd);
    Some(0)
}

// M1h (2026-05-29) — `handle_settings_plugins_keydown` removed. It existed only
// to close the (now-deleted) plugins MODAL on Esc; the inline §11 Plugins
// section has no modal, and Esc on the Settings panel already closes the whole
// surface via the auxiliary-escape path.

fn handle_settings_passphrase_char(root: &AppRoot, codepoint: u32) -> bool {
    if matches!(codepoint, VK_BACKSPACE | VK_ENTER | VK_ESCAPE_KEY) {
        return false;
    }
    let Some(ch) = char::from_u32(codepoint) else {
        return false;
    };
    if ch.is_control() {
        return false;
    }
    let app = root.app.borrow();
    if !app.settings_open.get() || !app.passphrase_entry_active.get() {
        return false;
    }
    let mut draft = app.passphrase_draft.borrow_mut();
    if draft.chars().count() < 128 {
        draft.push(ch);
    }
    true
}

/// M7 (2026-06-01) — WM_CHAR handler for the §2 妗岄潰璺緞 / 鐩戞帶鍊?inline text
/// fields (the focused-field model that generalises the passphrase-only path).
/// Gated on `settings_open && settings_focused_field 鈭?{DesktopPath,
/// WatchValues}`; appends the composed Unicode codepoint to the focused draft
/// via the pure `AppState::settings_focused_push_char` (which caps length, is
/// CJK-safe, and allows `\n` only for the WatchValues textarea). Marks the
/// panel dirty so Save lights up. Returns `true` when handled (so the WM_CHAR
/// dispatcher stops + redraws). The Passphrase field is NOT handled here — it
/// keeps `handle_settings_passphrase_char` + commit-on-Enter. CJK arrives as a
/// post-composition codepoint via WM_CHAR (no WM_IME_* needed — same as every
/// existing nano text field).
fn handle_settings_text_char(root: &AppRoot, codepoint: u32) -> bool {
    // Reject the control codepoints the keydown path owns (Backspace/Enter/Esc)
    // so they never double-route into the draft.
    if matches!(codepoint, VK_BACKSPACE | VK_ENTER | VK_ESCAPE_KEY) {
        return false;
    }
    let Some(ch) = char::from_u32(codepoint) else {
        return false;
    };
    let app = root.app.borrow();
    if !app.settings_open.get() {
        return false;
    }
    if !matches!(
        app.settings_focused_field.get(),
        bento_nano_app::SettingsTextField::DesktopPath
            | bento_nano_app::SettingsTextField::WatchValues
            | bento_nano_app::SettingsTextField::AccentColor
    ) {
        return false;
    }
    if app.settings_focused_push_char(ch) {
        app.settings_dirty.set(true);
        true
    } else {
        // Field is focused but the char was rejected (control / over cap). Still
        // consume it so it never leaks to DefWindowProc.
        true
    }
}

/// M7 — WM_KEYDOWN handler for the §2 妗岄潰璺緞 / 鐩戞帶鍊?inline text fields.
/// Returns `Some(0)` (consumed) ONLY when a non-passphrase field is focused;
/// otherwise `None` so the passphrase + auxiliary-escape paths still run.
/// - Backspace → pop last scalar, mark dirty, redraw.
/// - Enter → DesktopPath (single line): blur the field; WatchValues (textarea):
///   insert a `\n` into the draft.
/// - Esc → blur the field (set `None`) + return `None`, allowing the same
///   keydown to reach the Settings auxiliary-escape close/cancel path.
fn handle_settings_text_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> Option<LRESULT> {
    let field = {
        let app = root.app.borrow();
        if !app.settings_open.get() {
            return None;
        }
        app.settings_focused_field.get()
    };
    let is_text_field = matches!(
        field,
        bento_nano_app::SettingsTextField::DesktopPath
            | bento_nano_app::SettingsTextField::WatchValues
            | bento_nano_app::SettingsTextField::AccentColor
    );
    if !is_text_field {
        return None;
    }
    match vk {
        VK_BACKSPACE => {
            let app = root.app.borrow();
            if app.settings_focused_backspace() {
                app.settings_dirty.set(true);
            }
            drop(app);
            request_redraw(hwnd);
            Some(0)
        }
        VK_ENTER => {
            let app = root.app.borrow();
            if matches!(field, bento_nano_app::SettingsTextField::WatchValues) {
                // Textarea: Enter inserts a newline (one watch path per line).
                if app.settings_focused_push_char('\n') {
                    app.settings_dirty.set(true);
                }
            } else {
                // Single-line input: Enter blurs the field.
                app.settings_focused_field
                    .set(bento_nano_app::SettingsTextField::None);
            }
            drop(app);
            request_redraw(hwnd);
            Some(0)
        }
        VK_ESCAPE_KEY => {
            // Blur first, then let this same keydown close/cancel Settings.
            let app = root.app.borrow();
            app.settings_focused_field
                .set(bento_nano_app::SettingsTextField::None);
            drop(app);
            request_redraw(hwnd);
            None
        }
        _ => None,
    }
}

fn handle_zone_editor_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> LRESULT {
    match vk {
        VK_BACKSPACE => {
            let app = root.app.borrow();
            if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
                let _ = session.draft_name.pop();
            }
            request_redraw(hwnd);
            0
        }
        VK_F2_KEY => {
            cycle_zone_editor_icon(root);
            request_redraw(hwnd);
            0
        }
        VK_F3_KEY => {
            cycle_zone_editor_accent(root);
            request_redraw(hwnd);
            0
        }
        VK_F4_KEY => {
            cycle_zone_editor_grid_columns(root);
            request_redraw(hwnd);
            0
        }
        VK_F5_KEY => {
            cycle_zone_editor_capsule(root);
            request_redraw(hwnd);
            0
        }
        VK_ENTER => {
            save_zone_editor(root);
            // SAFETY: hwnd is the live ZoneEditor HWND that received this key.
            unsafe { ShowWindow(hwnd, SW_HIDE) };
            if let Some(main) = find_main_hwnd(root) {
                request_redraw(main);
            }
            0
        }
        VK_ESCAPE_KEY => {
            root.app.borrow().zone_editor.borrow_mut().take();
            // SAFETY: hwnd is the live ZoneEditor HWND that received this key.
            unsafe { ShowWindow(hwnd, SW_HIDE) };
            0
        }
        _ => 0,
    }
}

fn handle_zone_editor_lbutton_up(root: &AppRoot, hwnd: HWND, x: f32, y: f32) -> bool {
    let hit = {
        let app = root.app.borrow();
        zone_editor_geometry::zone_editor_hit_test(app.viewport, x, y)
    };
    let Some(hit) = hit else {
        return false;
    };
    log_static(
        format!(
            "zone-editor: lbutton_up x={x:.1} y={y:.1} viewport={:.1}x{:.1} hit={hit:?}\n",
            root.app.borrow().viewport.width,
            root.app.borrow().viewport.height,
        )
        .as_str(),
    );
    match hit {
        ZoneEditorHit::Close => {
            root.app.borrow().zone_editor.borrow_mut().take();
            hide_aux_and_redraw_main(root, hwnd);
            return true;
        }
        ZoneEditorHit::Name => {
            focus_window_for_keyboard(hwnd);
        }
        ZoneEditorHit::Icon => {
            if !queue_zone_editor_icon_picker(root) {
                return false;
            }
        }
        ZoneEditorHit::AccentClear => {
            let app = root.app.borrow();
            if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
                session.draft_accent_color = None;
            }
        }
        ZoneEditorHit::AccentSwatch(index) => {
            let Some(accent) = ACCENT_PALETTE.get(index) else {
                return false;
            };
            let app = root.app.borrow();
            if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
                session.draft_accent_color = Some(SmolStr::new_static(accent));
            }
        }
        ZoneEditorHit::AccentCustom => {
            let initial = {
                let app = root.app.borrow();
                app.zone_editor
                    .borrow()
                    .as_ref()
                    .and_then(|session| session.draft_accent_color.clone())
                    .unwrap_or_else(|| SmolStr::new_static("#3b82f6"))
            };
            if let Some(accent) = choose_native_accent_color(hwnd, initial.as_str()) {
                let app = root.app.borrow();
                if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
                    session.draft_accent_color = Some(accent);
                }
            }
        }
        ZoneEditorHit::GridColumns(columns) => {
            let app = root.app.borrow();
            if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
                session.draft_grid_columns = columns.clamp(GRID_COLUMNS_MIN, GRID_COLUMNS_MAX);
            }
        }
        ZoneEditorHit::CapsuleSize(size) => set_zone_editor_capsule_size(root, size),
        ZoneEditorHit::CapsuleShape(shape) => set_zone_editor_capsule_shape(root, shape),
        ZoneEditorHit::Save => {
            save_zone_editor(root);
            hide_aux_and_redraw_main(root, hwnd);
            return true;
        }
        ZoneEditorHit::Cancel => {
            root.app.borrow().zone_editor.borrow_mut().take();
            hide_aux_and_redraw_main(root, hwnd);
            return true;
        }
    }
    request_redraw(hwnd);
    true
}

fn queue_zone_editor_icon_picker(root: &AppRoot) -> bool {
    let zone_id = {
        let app = root.app.borrow();
        app.zone_editor
            .borrow()
            .as_ref()
            .map(|session| session.zone_id)
    };
    let Some(zone_id) = zone_id else {
        return false;
    };
    root.dispatcher.push(Command::OpenIconPicker {
        zone_id: Some(zone_id),
    });
    true
}

fn cycle_zone_editor_icon(root: &AppRoot) {
    let app = root.app.borrow();
    let mut editor = app.zone_editor.borrow_mut();
    let Some(session) = editor.as_mut() else {
        return;
    };
    session.draft_icon = next_icon_slug(session.draft_icon.as_str());
}

fn cycle_zone_editor_accent(root: &AppRoot) {
    let app = root.app.borrow();
    let mut editor = app.zone_editor.borrow_mut();
    let Some(session) = editor.as_mut() else {
        return;
    };
    session.draft_accent_color = match session.draft_accent_color.as_deref() {
        None => Some(SmolStr::new_static(ACCENT_PALETTE[0])),
        Some(current) => match ACCENT_PALETTE.iter().position(|hex| *hex == current) {
            Some(idx) if idx + 1 < ACCENT_PALETTE.len() => {
                Some(SmolStr::new_static(ACCENT_PALETTE[idx + 1]))
            }
            Some(_) => None,
            None => Some(SmolStr::new_static(ACCENT_PALETTE[0])),
        },
    };
}

fn cycle_zone_editor_grid_columns(root: &AppRoot) {
    let app = root.app.borrow();
    let mut editor = app.zone_editor.borrow_mut();
    let Some(session) = editor.as_mut() else {
        return;
    };
    session.draft_grid_columns = if session.draft_grid_columns >= GRID_COLUMNS_MAX {
        GRID_COLUMNS_MIN
    } else {
        session.draft_grid_columns + 1
    };
}

fn cycle_zone_editor_capsule(root: &AppRoot) {
    let app = root.app.borrow();
    let mut editor = app.zone_editor.borrow_mut();
    let Some(session) = editor.as_mut() else {
        return;
    };
    let next_idx = ZONE_EDITOR_CAPSULE_PRESETS
        .iter()
        .position(|(size, shape)| {
            session.draft_capsule_size.as_str() == size.wire()
                && session.draft_capsule_shape.as_str() == shape.wire()
        })
        .map_or(0, |idx| (idx + 1) % ZONE_EDITOR_CAPSULE_PRESETS.len());
    let (size, shape) = ZONE_EDITOR_CAPSULE_PRESETS[next_idx];
    session.draft_capsule_size = SmolStr::new_static(size.wire());
    session.draft_capsule_shape = SmolStr::new_static(shape.wire());
}

fn set_zone_editor_capsule_size(root: &AppRoot, size: CapsuleSizeChoice) {
    let app = root.app.borrow();
    if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
        session.draft_capsule_size = SmolStr::new_static(size.wire());
    }
}

fn set_zone_editor_capsule_shape(root: &AppRoot, shape: CapsuleShapeChoice) {
    let app = root.app.borrow();
    if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
        session.draft_capsule_shape = SmolStr::new_static(shape.wire());
    }
}

fn handle_zone_editor_char(root: &AppRoot, codepoint: u32) {
    if matches!(codepoint, VK_BACKSPACE | VK_ENTER | VK_ESCAPE_KEY) {
        return;
    }
    let Some(ch) = char::from_u32(codepoint) else {
        return;
    };
    if ch.is_control() {
        return;
    }
    let app = root.app.borrow();
    if let Some(session) = app.zone_editor.borrow_mut().as_mut() {
        if session.draft_name.chars().count() < NAME_MAX_LEN {
            session.draft_name.push(ch);
        }
    }
}

fn save_zone_editor(root: &AppRoot) {
    let session = {
        let app = root.app.borrow();
        app.zone_editor.borrow_mut().take()
    };
    let Some(session) = session else {
        return;
    };
    let trimmed = session.draft_name.trim();
    if !trimmed.is_empty() {
        root.dispatcher
            .push(Command::RenameZone(session.zone_id, SmolStr::new(trimmed)));
    }
    root.dispatcher.push(Command::SetZoneAlias(
        session.zone_id,
        SmolStr::new_static(""),
    ));
    root.dispatcher.push(Command::SetZoneIcon(
        session.zone_id,
        normalize_icon_slug(session.draft_icon.as_str()),
    ));
    root.dispatcher.push(Command::SetZoneAccent(
        session.zone_id,
        session.draft_accent_color,
    ));
    root.dispatcher.push(Command::SetZoneGridColumns(
        session.zone_id,
        session.draft_grid_columns,
    ));
    root.dispatcher.push(Command::SetZoneCapsule(
        session.zone_id,
        session.draft_capsule_size,
        session.draft_capsule_shape,
    ));
}

fn handle_item_file_rename_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> LRESULT {
    match vk {
        VK_BACKSPACE => {
            let app = root.app.borrow();
            if let Some(session) = app.item_file_rename.borrow_mut().as_mut() {
                let _ = session.draft_name.pop();
                session.status = None;
            }
            request_redraw(hwnd);
            0
        }
        VK_ENTER => {
            if save_item_file_rename(root) {
                hide_aux_and_redraw_main(root, hwnd);
            } else {
                request_redraw(hwnd);
            }
            0
        }
        VK_ESCAPE_KEY => {
            root.app.borrow().item_file_rename.borrow_mut().take();
            hide_aux_and_redraw_main(root, hwnd);
            0
        }
        _ => 0,
    }
}

fn handle_item_file_rename_char(root: &AppRoot, codepoint: u32) {
    if matches!(codepoint, VK_BACKSPACE | VK_ENTER | VK_ESCAPE_KEY) {
        return;
    }
    let Some(ch) = char::from_u32(codepoint) else {
        return;
    };
    if ch.is_control() {
        return;
    }
    let app = root.app.borrow();
    if let Some(session) = app.item_file_rename.borrow_mut().as_mut() {
        if session.draft_name.chars().count() < 128 {
            session.draft_name.push(ch);
            session.status = None;
        }
    }
}

fn save_item_file_rename(root: &AppRoot) -> bool {
    let command = {
        let app = root.app.borrow();
        let mut session = app.item_file_rename.borrow_mut();
        let Some(session) = session.as_mut() else {
            return false;
        };
        match normalized_rename_leaf(session.draft_name.as_str()) {
            Ok(name) => Command::RenameItemFile(
                session.zone_id,
                bento_nano_app::ItemId(session.item_id.0),
                SmolStr::new(name),
            ),
            Err(error) => {
                let status = SmolStr::new(
                    if bento_nano_style::current_locale_is(&bento_nano_style::ZH_CN) {
                        format!("无法重命名：{error}")
                    } else {
                        format!("Rename rejected: {error}")
                    },
                );
                session.status = Some(status.clone());
                app.item_operation_status.borrow_mut().replace(status);
                return false;
            }
        }
    };
    root.app.borrow().item_file_rename.borrow_mut().take();
    root.dispatcher.push(command);
    true
}

fn handle_icon_picker_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> LRESULT {
    match vk {
        VK_F2_KEY | VK_RIGHT_KEY => {
            cycle_icon_picker_icon(root);
            request_redraw(hwnd);
            0
        }
        VK_ENTER => {
            save_icon_picker(root);
            hide_aux_and_redraw_main(root, hwnd);
            0
        }
        VK_ESCAPE_KEY => {
            root.app.borrow().icon_picker.borrow_mut().take();
            // SAFETY: hwnd is the live IconPicker HWND that received this key.
            unsafe { ShowWindow(hwnd, SW_HIDE) };
            0
        }
        _ => 0,
    }
}

fn cycle_icon_picker_icon(root: &AppRoot) {
    let app = root.app.borrow();
    let mut picker = app.icon_picker.borrow_mut();
    let Some(session) = picker.as_mut() else {
        return;
    };
    session.selected_icon = next_icon_slug(session.selected_icon.as_str());
}

fn save_icon_picker(root: &AppRoot) {
    let session = {
        let app = root.app.borrow();
        app.icon_picker.borrow_mut().take()
    };
    let Some(session) = session else {
        return;
    };
    let Some(zone_id) = session.zone_id else {
        let selected_icon = normalize_icon_slug(session.selected_icon.as_str());
        let ids = {
            let app = root.app.borrow();
            app.bulk_manager.borrow().selected().to_vec()
        };
        if ids.is_empty() {
            let app = root.app.borrow();
            app.bulk_manager_status
                .borrow_mut()
                .replace(SmolStr::new_static(
                    "No BulkManager zones selected for icon",
                ));
        } else {
            let updates = ids
                .iter()
                .map(|id| BulkZoneUpdate {
                    id: *id,
                    icon: Some(selected_icon.clone()),
                    ..BulkZoneUpdate::default()
                })
                .collect();
            root.dispatcher.push(Command::BulkUpdateZones(updates));
        }
        return;
    };
    let zone_exists = {
        let app = root.app.borrow();
        app.zones.get(zone_id).is_some()
    };
    if zone_exists {
        root.dispatcher.push(Command::SetZoneIcon(
            zone_id,
            normalize_icon_slug(session.selected_icon.as_str()),
        ));
    } else {
        tracing::warn!(
            target: "bentodesk::picker",
            ?zone_id,
            "IconPicker Enter ignored: target zone is gone"
        );
    }
}

fn icon_picker_slug_for_hit(hit: IconPickerHit) -> Option<SmolStr> {
    match hit {
        IconPickerHit::Icon(index) => ALL_ICON_KINDS
            .get(index)
            .map(|kind| SmolStr::new_static(kind.as_str())),
        IconPickerHit::Close => None,
    }
}

fn handle_icon_picker_lbutton_up(root: &AppRoot, hwnd: HWND, x: f32, y: f32) -> bool {
    let hit = {
        let app = root.app.borrow();
        picker_geometry::icon_picker_hit_test(app.viewport, x, y, ALL_ICON_KINDS.len())
    };
    let Some(hit) = hit else {
        return false;
    };
    if hit == IconPickerHit::Close {
        root.app.borrow().icon_picker.borrow_mut().take();
        hide_aux_and_redraw_main(root, hwnd);
        return true;
    }
    let Some(selected_icon) = icon_picker_slug_for_hit(hit) else {
        return false;
    };
    {
        let app = root.app.borrow();
        if let Some(session) = app.icon_picker.borrow_mut().as_mut() {
            session.selected_icon = selected_icon;
        }
    }
    save_icon_picker(root);
    hide_aux_and_redraw_main(root, hwnd);
    true
}

fn next_icon_slug(current: &str) -> SmolStr {
    let current = IconKind::from_str_opt(current)
        .map(IconKind::as_str)
        .unwrap_or(current);
    let next_idx = ALL_ICON_KINDS
        .iter()
        .position(|kind| kind.as_str() == current)
        .map_or(0, |idx| (idx + 1) % ALL_ICON_KINDS.len());
    SmolStr::new_static(ALL_ICON_KINDS[next_idx].as_str())
}

fn normalize_icon_slug(raw: &str) -> SmolStr {
    IconKind::from_str_opt(raw).map_or_else(
        || SmolStr::new_static(DEFAULT_ZONE_ICON),
        |kind| SmolStr::new_static(kind.as_str()),
    )
}

fn handle_palette_picker_keydown(root: &AppRoot, vk: u32, hwnd: HWND) -> LRESULT {
    match vk {
        VK_F3_KEY | VK_RIGHT_KEY => {
            cycle_palette_picker_accent(root);
            request_redraw(hwnd);
            0
        }
        VK_ENTER => {
            save_palette_picker(root);
            hide_aux_and_redraw_main(root, hwnd);
            0
        }
        VK_ESCAPE_KEY => {
            root.app.borrow().palette_picker.borrow_mut().take();
            // SAFETY: hwnd is the live PalettePicker HWND that received this key.
            unsafe { ShowWindow(hwnd, SW_HIDE) };
            0
        }
        _ => 0,
    }
}

fn cycle_palette_picker_accent(root: &AppRoot) {
    let app = root.app.borrow();
    let mut picker = app.palette_picker.borrow_mut();
    let Some(session) = picker.as_mut() else {
        return;
    };
    session.selected_accent = next_palette_accent(session.selected_accent.as_deref());
}

fn save_palette_picker(root: &AppRoot) {
    let session = {
        let app = root.app.borrow();
        app.palette_picker.borrow_mut().take()
    };
    let Some(session) = session else {
        return;
    };
    match session.target {
        PaletteTarget::ZoneAccent(zone_id) => {
            let zone_exists = {
                let app = root.app.borrow();
                app.zones.get(zone_id).is_some()
            };
            if zone_exists {
                root.dispatcher
                    .push(Command::SetZoneAccent(zone_id, session.selected_accent));
            } else {
                tracing::warn!(
                    target: "bentodesk::picker",
                    ?zone_id,
                    "PalettePicker Enter ignored: target zone is gone"
                );
            }
        }
        PaletteTarget::ThemeBase => {
            root.dispatcher
                .push(Command::SetThemeBase(session.selected_accent));
        }
        PaletteTarget::BulkManagerSelectedAccent => {
            let ids = {
                let app = root.app.borrow();
                app.bulk_manager.borrow().selected().to_vec()
            };
            if ids.is_empty() {
                let app = root.app.borrow();
                app.bulk_manager_status
                    .borrow_mut()
                    .replace(SmolStr::new_static(
                        "No BulkManager zones selected for color",
                    ));
            } else {
                let accent = session.selected_accent.unwrap_or_default();
                let updates = ids
                    .iter()
                    .map(|id| BulkZoneUpdate {
                        id: *id,
                        accent_color: Some(accent.clone()),
                        ..BulkZoneUpdate::default()
                    })
                    .collect();
                root.dispatcher.push(Command::BulkUpdateZones(updates));
            }
        }
    }
}

fn palette_picker_accent_for_hit(hit: PalettePickerHit) -> Option<Option<SmolStr>> {
    match hit {
        PalettePickerHit::Swatch(index) => palette_picker::swatch_table()
            .get(index)
            .map(|swatch| Some(swatch.hex.clone())),
        PalettePickerHit::Clear => Some(None),
    }
}

fn handle_palette_picker_lbutton_up(root: &AppRoot, hwnd: HWND, x: f32, y: f32) -> bool {
    let swatch_count = palette_picker::swatch_table().len();
    let hit = {
        let app = root.app.borrow();
        picker_geometry::palette_picker_hit_test(app.viewport, x, y, swatch_count)
    };
    let Some(selected_accent) = hit.and_then(palette_picker_accent_for_hit) else {
        return false;
    };
    {
        let app = root.app.borrow();
        if let Some(session) = app.palette_picker.borrow_mut().as_mut() {
            session.selected_accent = selected_accent;
        }
    }
    save_palette_picker(root);
    hide_aux_and_redraw_main(root, hwnd);
    true
}

fn hide_aux_and_redraw_main(root: &AppRoot, hwnd: HWND) {
    unsafe { ShowWindow(hwnd, SW_HIDE) };
    if let Some(main) = find_main_hwnd(root) {
        request_redraw(main);
    }
}

const SETTING_DISPLAY_LOCALE: &str = "display.locale";
const SETTING_UPDATES_CHECK_FREQUENCY: &str = "updates.check_frequency";
const SETTING_UPDATES_AUTO_DOWNLOAD: &str = "updates.auto_download";
const SETTING_UPDATES_SKIPPED_VERSION: &str = "updates.skipped_version";
const SETTING_STEALTH_ENABLED: &str = "stealth.enabled";
const SETTING_ENCRYPTION_MODE: &str = "encryption.mode";
const SETTING_APPEARANCE_ACCENT_COLOR: &str = "accent_color";
const SETTING_THEME_BASE_ACCENT: &str = "theme.base_accent";
const SETTING_ACTIVE_THEME: &str = "active_theme";
const SETTING_ZONE_DISPLAY_MODE: &str = "zone_display_mode";
const SETTING_DEBUG_OVERLAY: &str = "debug_overlay";
const SETTING_MINIBAR_PINNED_ZONES: &str = "minibar.pinned_zones";
// M1a 2026-05-29 — General-section persistence keys. Names mirror Tauri's
// `AppSettings` field names in dotted form (see `bentodesk/src/types/settings.ts`
// and `updateSettingsStore` at `SettingsPanel.tsx:216-227`) so a future
// vault file ported between the two builds reads back identically.
const SETTING_GENERAL_GHOST_LAYER_ENABLED: &str = "general.ghost_layer_enabled";
const SETTING_GENERAL_LAUNCH_AT_STARTUP: &str = "general.launch_at_startup";
const SETTING_GENERAL_SHOW_IN_TASKBAR: &str = "general.show_in_taskbar";
const SETTING_GENERAL_AUTO_GROUP_ENABLED: &str = "general.auto_group_enabled";
const SETTING_GENERAL_PORTABLE_MODE: &str = "general.portable_mode";
// M1d 2026-05-29 — Performance §5 + Startup management §6 persistence keys.
// Dotted names mirror Tauri's `AppSettings` (`performance.*` / `startup.*`)
// so a vault file stays portable between the two builds.
const SETTING_PERF_EXPAND_DELAY_MS: &str = "performance.expand_delay_ms";
const SETTING_PERF_COLLAPSE_DELAY_MS: &str = "performance.collapse_delay_ms";
const SETTING_PERF_ICON_CACHE_SIZE: &str = "performance.icon_cache_size";
const SETTING_STARTUP_HIGH_PRIORITY: &str = "startup.high_priority";
const SETTING_STARTUP_CRASH_RESTART_ENABLED: &str = "startup.crash_restart_enabled";
const SETTING_STARTUP_CRASH_MAX_RETRIES: &str = "startup.crash_max_retries";
const SETTING_STARTUP_CRASH_WINDOW_SECS: &str = "startup.crash_window_secs";
const SETTING_STARTUP_SAFE_AFTER_HIBERNATION: &str = "startup.safe_start_after_hibernation";
const SETTING_STARTUP_HIBERNATE_RESUME_DELAY_MS: &str = "startup.hibernate_resume_delay_ms";
// W1 (#7 fix wave 2026-06-01) — §2 Paths persistence keys. Tauri keys these as
// `desktop_path` (string) + `watch_paths` (string[]). The nano vault stores
// scalars, so the watch list persists as a single newline-joined `Str` (one
// path per line) — exactly the in-memory `watch_paths_draft` shape. The dotted
// `paths.*` names follow the existing `general.*` / `performance.*` convention.
const SETTING_PATHS_DESKTOP_PATH: &str = "paths.desktop_path";
const SETTING_PATHS_WATCH_PATHS: &str = "paths.watch_paths";

/// M1a 2026-05-29 — restore each General-section AppState Cell from the
/// persisted vault values written by `save_settings_general`. Absent keys
/// keep the AppState defaults so a fresh installation reads as the
/// designed-default toggle layout (matches Tauri's `defaultAppSettings`
/// fall-through in `stores/settings.ts`).
///
/// Called once from `apply_persisted_settings_from_vault` after the locale /
/// updater frequency restores so the General section is in its persisted
/// state before the panel can render. Returns silently when the vault
/// global is not yet installed (early startup before `init_global` runs);
/// callers must tolerate that branch without retrying.
fn apply_general_settings_from_vault(app: &AppState) {
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        return;
    };
    let Ok(vault) = mtx.lock() else {
        tracing::warn!(
            target: "bentodesk::vault",
            "general settings restore skipped: vault mutex poisoned"
        );
        return;
    };
    let ghost = vault.get_setting(SETTING_GENERAL_GHOST_LAYER_ENABLED);
    let startup = vault.get_setting(SETTING_GENERAL_LAUNCH_AT_STARTUP);
    let taskbar = vault.get_setting(SETTING_GENERAL_SHOW_IN_TASKBAR);
    let auto_group = vault.get_setting(SETTING_GENERAL_AUTO_GROUP_ENABLED);
    let portable = vault.get_setting(SETTING_GENERAL_PORTABLE_MODE);
    // M1d — Performance §5 + Startup management §6 reads.
    let expand_delay = vault.get_setting(SETTING_PERF_EXPAND_DELAY_MS);
    let collapse_delay = vault.get_setting(SETTING_PERF_COLLAPSE_DELAY_MS);
    let icon_cache = vault.get_setting(SETTING_PERF_ICON_CACHE_SIZE);
    let high_priority = vault.get_setting(SETTING_STARTUP_HIGH_PRIORITY);
    let crash_restart = vault.get_setting(SETTING_STARTUP_CRASH_RESTART_ENABLED);
    let crash_retries = vault.get_setting(SETTING_STARTUP_CRASH_MAX_RETRIES);
    let crash_window = vault.get_setting(SETTING_STARTUP_CRASH_WINDOW_SECS);
    let safe_start = vault.get_setting(SETTING_STARTUP_SAFE_AFTER_HIBERNATION);
    let hibernate_delay = vault.get_setting(SETTING_STARTUP_HIBERNATE_RESUME_DELAY_MS);
    // W1 (#7 fix wave) — rehydrate the two §2 Paths drafts so path/watch edits
    // survive a relaunch (they were dropped on flush before this fix).
    let desktop_path = vault.get_setting(SETTING_PATHS_DESKTOP_PATH);
    let watch_paths = vault.get_setting(SETTING_PATHS_WATCH_PATHS);
    drop(vault);

    restore_general_bool_cell(&app.setting_desktop_embed, ghost, "ghost_layer_enabled");
    restore_general_bool_cell(&app.setting_autostart, startup, "launch_at_startup");
    // Mc-3 #12 — HKCU\Run is the real source of truth; the toggle previously
    // never wrote it. Override the persisted mirror with the actual registry
    // state so the UI is honest. Display-only (no boot re-assert → respects
    // Task Manager disable).
    app.setting_autostart
        .set(bento_nano_backend::autostart::is_enabled());
    restore_general_bool_cell(&app.setting_show_in_taskbar, taskbar, "show_in_taskbar");
    restore_general_bool_cell(&app.setting_smart_layout, auto_group, "auto_group_enabled");
    restore_general_bool_cell(&app.setting_portable_mode, portable, "portable_mode");
    // M1d — clamp persisted ints back to their Tauri bounds on restore so a
    // hand-edited / ported vault can never push a slider out of range.
    use bento_nano_app::state::{
        COLLAPSE_DELAY_MAX_MS, COLLAPSE_DELAY_MIN_MS, CRASH_MAX_RETRIES_MAX, CRASH_MAX_RETRIES_MIN,
        CRASH_WINDOW_SECS_MAX, CRASH_WINDOW_SECS_MIN, EXPAND_DELAY_MAX_MS, EXPAND_DELAY_MIN_MS,
        HIBERNATE_DELAY_MAX_MS, HIBERNATE_DELAY_MIN_MS, ICON_CACHE_MAX, ICON_CACHE_MIN,
    };
    restore_general_int_cell(
        &app.expand_delay_ms,
        expand_delay,
        EXPAND_DELAY_MIN_MS,
        EXPAND_DELAY_MAX_MS,
        "expand_delay_ms",
    );
    restore_general_int_cell(
        &app.collapse_delay_ms,
        collapse_delay,
        COLLAPSE_DELAY_MIN_MS,
        COLLAPSE_DELAY_MAX_MS,
        "collapse_delay_ms",
    );
    restore_general_int_cell(
        &app.icon_cache_size,
        icon_cache,
        ICON_CACHE_MIN,
        ICON_CACHE_MAX,
        "icon_cache_size",
    );
    restore_general_bool_cell(
        &app.startup_high_priority,
        high_priority,
        "startup_high_priority",
    );
    restore_general_bool_cell(
        &app.crash_restart_enabled,
        crash_restart,
        "crash_restart_enabled",
    );
    restore_general_int_cell(
        &app.crash_max_retries,
        crash_retries,
        CRASH_MAX_RETRIES_MIN,
        CRASH_MAX_RETRIES_MAX,
        "crash_max_retries",
    );
    restore_general_int_cell(
        &app.crash_window_secs,
        crash_window,
        CRASH_WINDOW_SECS_MIN,
        CRASH_WINDOW_SECS_MAX,
        "crash_window_secs",
    );
    restore_general_bool_cell(
        &app.safe_start_after_hibernation,
        safe_start,
        "safe_start_after_hibernation",
    );
    restore_general_int_cell(
        &app.hibernate_resume_delay_ms,
        hibernate_delay,
        HIBERNATE_DELAY_MIN_MS,
        HIBERNATE_DELAY_MAX_MS,
        "hibernate_resume_delay_ms",
    );
    // W1 (#7 fix wave) — apply the two §2 Paths drafts. Absent keys keep the
    // AppState defaults (`D:\\Desktop` / empty) so a fresh install reads as
    // designed; a persisted (possibly empty) string overrides them.
    restore_general_str_cell(&app.desktop_path_draft, desktop_path, "desktop_path");
    restore_general_str_cell(&app.watch_paths_draft, watch_paths, "watch_paths");
}

/// W1 2026-06-01 — apply a `SettingValue::Str` to one §2 Paths draft
/// `RefCell<SmolStr>`, logging if the persisted value has the wrong tag. `None`
/// keeps the AppState default (silent — first-launch path).
fn restore_general_str_cell(
    cell: &std::cell::RefCell<SmolStr>,
    value: Option<bento_nano_backend::config_vault::SettingValue>,
    label: &'static str,
) {
    match value {
        Some(bento_nano_backend::config_vault::SettingValue::Str(s)) => {
            *cell.borrow_mut() = s;
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                key = %label,
                "general settings restore skipped: non-str value"
            );
        }
        None => {}
    }
}

/// M1d 2026-05-29 — apply a `SettingValue::Int` to one `Cell<i32>`, clamped to
/// `[min, max]`, logging if the persisted value has the wrong tag. `None`
/// keeps the AppState default (silent — first-launch path). The clamp guards
/// a hand-edited / ported vault from pushing a slider out of its Tauri range.
fn restore_general_int_cell(
    cell: &std::cell::Cell<i32>,
    value: Option<bento_nano_backend::config_vault::SettingValue>,
    min: i32,
    max: i32,
    label: &'static str,
) {
    match value {
        Some(bento_nano_backend::config_vault::SettingValue::Int(i)) => {
            let clamped = (i as i32).clamp(min, max);
            cell.set(clamped);
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                key = %label,
                "general settings restore skipped: non-int value"
            );
        }
        None => {}
    }
}

/// M1a 2026-05-29 — apply a `SettingValue::Bool` to one General-section
/// `Cell<bool>`, logging if the persisted value has the wrong tag. `None`
/// keeps the AppState default (silent — first-launch path).
fn restore_general_bool_cell(
    cell: &std::cell::Cell<bool>,
    value: Option<bento_nano_backend::config_vault::SettingValue>,
    label: &'static str,
) {
    match value {
        Some(bento_nano_backend::config_vault::SettingValue::Bool(b)) => cell.set(b),
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                key = %label,
                "general settings restore skipped: non-bool value"
            );
        }
        None => {}
    }
}

/// M1a 2026-05-29 — persist the 5 General toggle Cells to the config vault
/// in one batched write + flush. Wired to the footer Save click (and only
/// runs when `settings_dirty` is true; clean Save short-circuits). After
/// the write completes the dirty flag clears, leaving the panel in a
/// "just-saved" state until the next toggle.
fn persist_settings_accent_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    accent_draft: Option<&SmolStr>,
    clear_requested: bool,
) {
    if clear_requested {
        vault.remove_setting(SETTING_APPEARANCE_ACCENT_COLOR);
        vault.remove_setting(SETTING_THEME_BASE_ACCENT);
        return;
    }
    let Some(accent) = accent_draft else {
        return;
    };
    vault.set_setting(
        SETTING_APPEARANCE_ACCENT_COLOR,
        bento_nano_backend::config_vault::SettingValue::Str(accent.clone()),
    );
    vault.set_setting(
        SETTING_THEME_BASE_ACCENT,
        bento_nano_backend::config_vault::SettingValue::Str(accent.clone()),
    );
}

const SETTINGS_PROTECTED_PREFIXES: &[&str] = &[
    r"c:\windows",
    r"c:\program files",
    r"c:\program files (x86)",
    r"c:\programdata",
    r"c:\$recycle.bin",
    r"c:\system volume information",
];

const SETTINGS_TRANSACTION_KEYS: &[&str] = &[
    SETTING_GENERAL_GHOST_LAYER_ENABLED,
    SETTING_GENERAL_LAUNCH_AT_STARTUP,
    SETTING_GENERAL_SHOW_IN_TASKBAR,
    SETTING_GENERAL_AUTO_GROUP_ENABLED,
    SETTING_GENERAL_PORTABLE_MODE,
    SETTING_PERF_EXPAND_DELAY_MS,
    SETTING_PERF_COLLAPSE_DELAY_MS,
    SETTING_PERF_ICON_CACHE_SIZE,
    SETTING_STARTUP_HIGH_PRIORITY,
    SETTING_STARTUP_CRASH_RESTART_ENABLED,
    SETTING_STARTUP_CRASH_MAX_RETRIES,
    SETTING_STARTUP_CRASH_WINDOW_SECS,
    SETTING_STARTUP_SAFE_AFTER_HIBERNATION,
    SETTING_STARTUP_HIBERNATE_RESUME_DELAY_MS,
    SETTING_PATHS_DESKTOP_PATH,
    SETTING_PATHS_WATCH_PATHS,
    SETTING_APPEARANCE_ACCENT_COLOR,
    SETTING_THEME_BASE_ACCENT,
    SETTING_ACTIVE_THEME,
    SETTING_ZONE_DISPLAY_MODE,
];

fn settings_save_failure(root: &AppRoot, message: impl Into<SmolStr>) -> bool {
    let message = message.into();
    tracing::warn!(target: "bentodesk::settings", error = %message, "settings save rejected");
    let app = root.app.borrow();
    app.settings_dirty.set(true);
    app.settings_save_error.borrow_mut().replace(message);
    false
}

fn strip_windows_extended_path(path: &str) -> &str {
    path.strip_prefix(r"\\?\").unwrap_or(path)
}

fn settings_path_is_within_prefix(path: &str, prefix: &str) -> bool {
    path == prefix
        || path
            .strip_prefix(prefix)
            .is_some_and(|suffix| suffix.starts_with('\\'))
}

fn validate_settings_directory(raw: &str, label: &str) -> Result<PathBuf, SmolStr> {
    let raw = raw.trim();
    if raw.is_empty() {
        return Err(SmolStr::new(format!("{label}不能为空")));
    }
    let path = Path::new(raw);
    if !path.exists() {
        return Err(SmolStr::new(format!("{label}不存在：{raw}")));
    }
    if !path.is_dir() {
        return Err(SmolStr::new(format!("{label}不是文件夹：{raw}")));
    }
    let canonical = std::fs::canonicalize(path)
        .map_err(|error| SmolStr::new(format!("{label}无法解析：{error}")))?;
    let canonical_lower = strip_windows_extended_path(canonical.to_string_lossy().as_ref())
        .replace('/', "\\")
        .to_lowercase();
    if let Some(prefix) = SETTINGS_PROTECTED_PREFIXES
        .iter()
        .find(|prefix| settings_path_is_within_prefix(&canonical_lower, prefix))
    {
        return Err(SmolStr::new(format!("{label}不能位于系统目录 {prefix} 内")));
    }
    Ok(canonical)
}

fn push_unique_settings_source(sources: &mut Vec<PathBuf>, candidate: PathBuf) {
    let folded = candidate
        .to_string_lossy()
        .replace('/', "\\")
        .to_lowercase();
    if sources
        .iter()
        .any(|path| path.to_string_lossy().replace('/', "\\").to_lowercase() == folded)
    {
        return;
    }
    sources.push(candidate);
}

fn validate_settings_sources(snapshot: &SettingsSnapshot) -> Result<Vec<PathBuf>, SmolStr> {
    let desktop = validate_settings_directory(snapshot.desktop_path_draft.as_str(), "桌面路径")?;
    let desktop_text = desktop.to_string_lossy();
    let mut sources = Vec::new();
    for source in bento_nano_backend::desktop_sources::all_desktop_dirs(Some(&desktop_text)) {
        if source.is_dir() {
            push_unique_settings_source(
                &mut sources,
                std::fs::canonicalize(&source).unwrap_or(source),
            );
        }
    }
    // `all_desktop_dirs` deliberately filters missing paths. Keep the validated
    // custom path even if it was folded out as a duplicate.
    push_unique_settings_source(&mut sources, desktop);

    for (index, raw) in snapshot.watch_paths_draft.lines().enumerate() {
        let raw = raw.trim();
        if raw.is_empty() {
            continue;
        }
        let label = format!("监控路径第 {} 行", index + 1);
        let path = validate_settings_directory(raw, label.as_str())?;
        push_unique_settings_source(&mut sources, path);
    }
    if sources.is_empty() {
        return Err(SmolStr::new_static("没有可用的桌面监控路径"));
    }
    Ok(sources)
}

fn rebuild_desktop_watcher(root: &AppRoot, sources: &[PathBuf]) -> Result<(), SmolStr> {
    if startup_diag_skip("desktop_watcher") {
        tracing::info!(
            target: "bentodesk::watcher",
            "desktop watcher rebuild skipped by startup diagnostics"
        );
        return Ok(());
    }
    let replacement =
        bento_nano_backend::watcher::setup_file_watcher(sources, root.desktop_event_tx.clone())
            .map_err(|error| SmolStr::new(format!("无法监控桌面路径：{error}")))?;
    let previous = root.desktop_watcher.replace(Some(replacement));
    drop(previous);
    tracing::info!(
        target: "bentodesk::watcher",
        sources = sources.len(),
        "desktop watcher rebuilt from saved Settings paths"
    );
    Ok(())
}

fn copy_state_dir_recursive(source: &Path, target: &Path) -> Result<(), SmolStr> {
    if source == target || !source.exists() {
        return Ok(());
    }
    std::fs::create_dir_all(target)
        .map_err(|error| SmolStr::new(format!("无法创建便携数据目录：{error}")))?;
    let entries = std::fs::read_dir(source)
        .map_err(|error| SmolStr::new(format!("无法读取当前数据目录：{error}")))?;
    for entry in entries {
        let entry = entry.map_err(|error| SmolStr::new(format!("无法读取数据目录项：{error}")))?;
        let file_type = entry
            .file_type()
            .map_err(|error| SmolStr::new(format!("无法读取数据目录项类型：{error}")))?;
        let destination = target.join(entry.file_name());
        if file_type.is_symlink() {
            return Err(SmolStr::new(format!(
                "便携迁移拒绝符号链接：{}",
                entry.path().display()
            )));
        }
        if file_type.is_dir() {
            copy_state_dir_recursive(entry.path().as_path(), destination.as_path())?;
        } else if file_type.is_file() {
            std::fs::copy(entry.path(), &destination).map_err(|error| {
                SmolStr::new(format!(
                    "无法复制便携数据 {}：{error}",
                    entry.path().display()
                ))
            })?;
        }
    }
    Ok(())
}

fn sync_portable_state(previous: bool, desired: bool) -> Result<(), SmolStr> {
    if previous == desired {
        return Ok(());
    }
    let source = storage::state_dir_for_portable_mode(previous)
        .map_err(|error| SmolStr::new(format!("无法定位当前数据目录：{error}")))?;
    let target = storage::state_dir_for_portable_mode(desired)
        .map_err(|error| SmolStr::new(format!("无法定位目标数据目录：{error}")))?;
    copy_state_dir_recursive(source.as_path(), target.as_path())?;
    storage::set_portable_mode_enabled(desired)
        .map_err(|error| SmolStr::new(format!("无法切换便携模式：{error}")))?;
    tracing::info!(
        target: "bentodesk::settings",
        previous,
        desired,
        source = %source.display(),
        target_dir = %target.display(),
        "portable mode state synchronized for next launch"
    );
    Ok(())
}

fn apply_show_in_taskbar(hwnd: HWND, show: bool) -> Result<(), SmolStr> {
    if hwnd.is_null() {
        return Err(SmolStr::new_static("主窗口不存在，无法更新任务栏状态"));
    }
    let _guard = bento_nano_backend::ghost_layer::bypass_subclass_guard();
    // SAFETY: `hwnd` is the live Main HWND. The hide/style/frame/show sequence
    // matches the Tauri baseline and avoids stale taskbar buttons.
    unsafe {
        ShowWindow(hwnd, SW_HIDE);
        let current = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);
        let desired = if show {
            (current | WS_EX_APPWINDOW as isize) & !(WS_EX_TOOLWINDOW as isize)
        } else {
            (current | WS_EX_TOOLWINDOW as isize) & !(WS_EX_APPWINDOW as isize)
        };
        SetWindowLongPtrW(hwnd, GWL_EXSTYLE, desired);
        SetWindowPos(
            hwnd,
            ptr::null_mut(),
            0,
            0,
            0,
            0,
            SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE | SWP_FRAMECHANGED,
        );
        ShowWindow(hwnd, SW_SHOWNOACTIVATE);
        let applied = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);
        let correct = if show {
            applied & WS_EX_APPWINDOW as isize != 0 && applied & WS_EX_TOOLWINDOW as isize == 0
        } else {
            applied & WS_EX_TOOLWINDOW as isize != 0 && applied & WS_EX_APPWINDOW as isize == 0
        };
        if !correct {
            return Err(SmolStr::new_static("Windows 未接受任务栏窗口样式"));
        }
    }
    Ok(())
}

fn apply_desktop_embed(hwnd: HWND, enabled: bool) -> Result<(), SmolStr> {
    let result = if enabled {
        bento_nano_backend::ghost_layer::attach_selected_stack(hwnd)
    } else {
        bento_nano_backend::ghost_layer::detach(hwnd)
    };
    result.map_err(|error| SmolStr::new(format!("桌面嵌入切换失败：{error}")))
}

fn apply_process_priority(high_priority: bool) -> Result<(), SmolStr> {
    let priority = if high_priority {
        ABOVE_NORMAL_PRIORITY_CLASS
    } else {
        NORMAL_PRIORITY_CLASS
    };
    // SAFETY: GetCurrentProcess returns a process pseudo-handle valid for
    // SetPriorityClass. No ownership is transferred.
    if unsafe { SetPriorityClass(GetCurrentProcess(), priority) } == 0 {
        return Err(SmolStr::new(format!(
            "进程优先级切换失败：Win32 {}",
            unsafe { GetLastError() }
        )));
    }
    Ok(())
}

fn restart_arg_value(args: &[String], prefix: &str) -> Option<u64> {
    args.iter()
        .find_map(|arg| arg.strip_prefix(prefix)?.parse::<u64>().ok())
}

fn restart_registration_command(
    enabled: bool,
    max_retries: u32,
    window_secs: u64,
    now_secs: u64,
    args: &[String],
) -> Option<String> {
    if !enabled || max_retries == 0 {
        return None;
    }
    let mut attempt = restart_arg_value(args, RESTART_ATTEMPT_ARG).unwrap_or(0);
    let mut window_start = restart_arg_value(args, RESTART_WINDOW_START_ARG).unwrap_or(now_secs);
    if now_secs.saturating_sub(window_start) > window_secs {
        attempt = 0;
        window_start = now_secs;
    }
    if attempt >= u64::from(max_retries) {
        return None;
    }
    Some(format!(
        "{RESTART_ATTEMPT_ARG}{} {RESTART_WINDOW_START_ARG}{window_start}",
        attempt + 1
    ))
}

fn configure_application_restart(snapshot: &SettingsSnapshot) -> Result<(), SmolStr> {
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let args: Vec<String> = std::env::args().collect();
    let command = restart_registration_command(
        snapshot.crash_restart_enabled,
        snapshot.crash_max_retries.max(0) as u32,
        snapshot.crash_window_secs.max(0) as u64,
        now_secs,
        &args,
    );
    let hr = match command {
        Some(command) => {
            let wide = widen_dynamic(command.as_str());
            // SAFETY: `wide` is NUL-terminated and alive for the call.
            unsafe {
                RegisterApplicationRestart(
                    wide.as_ptr(),
                    RESTART_NO_HANG | RESTART_NO_PATCH | RESTART_NO_REBOOT,
                )
            }
        }
        None => {
            // SAFETY: process-scoped unregister has no arguments.
            unsafe { UnregisterApplicationRestart() }
        }
    };
    if hr < 0 {
        return Err(SmolStr::new(format!(
            "崩溃自动重启配置失败：HRESULT 0x{:08X}",
            hr as u32
        )));
    }
    Ok(())
}

fn settings_paths_changed(previous: &SettingsSnapshot, desired: &SettingsSnapshot) -> bool {
    previous.desktop_path_draft != desired.desktop_path_draft
        || previous.watch_paths_draft != desired.watch_paths_draft
}

fn apply_runtime_settings(
    root: &AppRoot,
    previous: &SettingsSnapshot,
    desired: &SettingsSnapshot,
    desired_sources: &[PathBuf],
) -> Result<(), SmolStr> {
    if previous.launch_at_startup != desired.launch_at_startup {
        bento_nano_backend::autostart::set_enabled(desired.launch_at_startup)
            .map_err(|error| SmolStr::new(format!("开机启动配置失败：{error}")))?;
        if bento_nano_backend::autostart::is_enabled() != desired.launch_at_startup {
            return Err(SmolStr::new_static("开机启动注册表状态校验失败"));
        }
    }

    let main_hwnd = find_main_hwnd(root);
    if previous.show_in_taskbar != desired.show_in_taskbar {
        apply_show_in_taskbar(
            main_hwnd.ok_or_else(|| SmolStr::new_static("主窗口尚未创建"))?,
            desired.show_in_taskbar,
        )?;
    }
    if previous.icon_cache_size != desired.icon_cache_size {
        let Some(cache) = bento_nano_backend::icon::cache_handle() else {
            return Err(SmolStr::new_static("图标缓存尚未初始化"));
        };
        cache.resize(desired.icon_cache_size.max(1) as usize);
    }
    if previous.ghost_layer_enabled != desired.ghost_layer_enabled {
        apply_desktop_embed(
            main_hwnd.ok_or_else(|| SmolStr::new_static("主窗口尚未创建"))?,
            desired.ghost_layer_enabled,
        )?;
    }
    if previous.startup_high_priority != desired.startup_high_priority {
        apply_process_priority(desired.startup_high_priority)?;
    }
    if previous.crash_restart_enabled != desired.crash_restart_enabled
        || previous.crash_max_retries != desired.crash_max_retries
        || previous.crash_window_secs != desired.crash_window_secs
    {
        configure_application_restart(desired)?;
    }
    if settings_paths_changed(previous, desired) {
        rebuild_desktop_watcher(root, desired_sources)?;
    }
    sync_portable_state(previous.portable_mode, desired.portable_mode)?;
    Ok(())
}

fn snapshot_vault_settings(
    vault: &bento_nano_backend::config_vault::Vault,
) -> Vec<(
    &'static str,
    Option<bento_nano_backend::config_vault::SettingValue>,
)> {
    SETTINGS_TRANSACTION_KEYS
        .iter()
        .map(|key| (*key, vault.get_setting(key)))
        .collect()
}

fn restore_vault_settings(
    vault: &mut bento_nano_backend::config_vault::Vault,
    values: &[(
        &'static str,
        Option<bento_nano_backend::config_vault::SettingValue>,
    )],
) {
    for (key, value) in values {
        match value {
            Some(value) => vault.set_setting(key, value.clone()),
            None => {
                vault.remove_setting(key);
            }
        }
    }
}

fn persist_settings_snapshot_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    snapshot: &SettingsSnapshot,
    accent_draft: Option<&SmolStr>,
    accent_clear_requested: bool,
) {
    vault.set_setting(
        SETTING_GENERAL_GHOST_LAYER_ENABLED,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.ghost_layer_enabled),
    );
    vault.set_setting(
        SETTING_GENERAL_LAUNCH_AT_STARTUP,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.launch_at_startup),
    );
    vault.set_setting(
        SETTING_GENERAL_SHOW_IN_TASKBAR,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.show_in_taskbar),
    );
    vault.set_setting(
        SETTING_GENERAL_AUTO_GROUP_ENABLED,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.auto_group_enabled),
    );
    vault.set_setting(
        SETTING_GENERAL_PORTABLE_MODE,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.portable_mode),
    );
    vault.set_setting(
        SETTING_PERF_EXPAND_DELAY_MS,
        bento_nano_backend::config_vault::SettingValue::Int(snapshot.expand_delay_ms as i64),
    );
    vault.set_setting(
        SETTING_PERF_COLLAPSE_DELAY_MS,
        bento_nano_backend::config_vault::SettingValue::Int(snapshot.collapse_delay_ms as i64),
    );
    vault.set_setting(
        SETTING_PERF_ICON_CACHE_SIZE,
        bento_nano_backend::config_vault::SettingValue::Int(snapshot.icon_cache_size as i64),
    );
    vault.set_setting(
        SETTING_STARTUP_HIGH_PRIORITY,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.startup_high_priority),
    );
    vault.set_setting(
        SETTING_STARTUP_CRASH_RESTART_ENABLED,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.crash_restart_enabled),
    );
    vault.set_setting(
        SETTING_STARTUP_CRASH_MAX_RETRIES,
        bento_nano_backend::config_vault::SettingValue::Int(snapshot.crash_max_retries as i64),
    );
    vault.set_setting(
        SETTING_STARTUP_CRASH_WINDOW_SECS,
        bento_nano_backend::config_vault::SettingValue::Int(snapshot.crash_window_secs as i64),
    );
    vault.set_setting(
        SETTING_STARTUP_SAFE_AFTER_HIBERNATION,
        bento_nano_backend::config_vault::SettingValue::Bool(snapshot.safe_start_after_hibernation),
    );
    vault.set_setting(
        SETTING_STARTUP_HIBERNATE_RESUME_DELAY_MS,
        bento_nano_backend::config_vault::SettingValue::Int(
            snapshot.hibernate_resume_delay_ms as i64,
        ),
    );
    persist_settings_accent_to_vault(vault, accent_draft, accent_clear_requested);
    vault.set_setting(
        SETTING_PATHS_DESKTOP_PATH,
        bento_nano_backend::config_vault::SettingValue::Str(snapshot.desktop_path_draft.clone()),
    );
    vault.set_setting(
        SETTING_PATHS_WATCH_PATHS,
        bento_nano_backend::config_vault::SettingValue::Str(snapshot.watch_paths_draft.clone()),
    );
    vault.set_setting(
        SETTING_ACTIVE_THEME,
        bento_nano_backend::config_vault::SettingValue::Str(snapshot.active_theme_id.clone()),
    );
    vault.set_setting(
        SETTING_ZONE_DISPLAY_MODE,
        bento_nano_backend::config_vault::SettingValue::Str(SmolStr::new_static(
            snapshot.zone_display_mode.as_wire(),
        )),
    );
}

fn save_settings_general(root: &AppRoot, _settings_hwnd: HWND) -> bool {
    let (dirty, desired, previous, accent_draft, accent_clear_requested) = {
        let app = root.app.borrow();
        (
            app.settings_dirty.get(),
            app.snapshot_settings(),
            app.settings_snapshot
                .borrow()
                .clone()
                .unwrap_or_else(|| app.snapshot_settings()),
            app.settings_valid_accent_draft(),
            app.settings_accent_clear_requested.get(),
        )
    };
    if !dirty {
        return false;
    }
    {
        let app = root.app.borrow();
        app.settings_save_error.borrow_mut().take();
    }
    let desired_sources = match validate_settings_sources(&desired) {
        Ok(sources) => sources,
        Err(error) => return settings_save_failure(root, error),
    };

    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        tracing::warn!(
            target: "bentodesk::vault",
            "settings: SaveSettings rejected — vault global not installed"
        );
        return settings_save_failure(root, "设置存储尚未初始化");
    };
    let original_values = {
        let Ok(mut vault) = mtx.lock() else {
            return settings_save_failure(root, "设置存储锁已损坏");
        };
        if vault.is_locked_passphrase() {
            return settings_save_failure(root, "请先解锁设置加密，再保存");
        }
        let original_values = snapshot_vault_settings(&vault);
        persist_settings_snapshot_to_vault(
            &mut vault,
            &desired,
            accent_draft.as_ref(),
            accent_clear_requested,
        );
        if let Err(error) = vault.flush() {
            restore_vault_settings(&mut vault, &original_values);
            let _ = vault.flush();
            return settings_save_failure(root, format!("设置写入失败：{error}"));
        }
        original_values
    };

    if let Err(error) = apply_runtime_settings(root, &previous, &desired, &desired_sources) {
        if let Ok(mut vault) = mtx.lock() {
            restore_vault_settings(&mut vault, &original_values);
            if let Err(rollback_error) = vault.flush() {
                tracing::error!(
                    target: "bentodesk::vault",
                    %rollback_error,
                    "settings rollback flush failed"
                );
            }
        }
        let previous_sources =
            validate_settings_sources(&previous).unwrap_or_else(|_| desired_sources.clone());
        if let Err(rollback_error) =
            apply_runtime_settings(root, &desired, &previous, &previous_sources)
        {
            tracing::error!(
                target: "bentodesk::settings",
                %rollback_error,
                "native Settings side-effect rollback failed"
            );
        }
        return settings_save_failure(root, error);
    }

    let app = root.app.borrow();
    app.settings_dirty.set(false);
    app.settings_snapshot.borrow_mut().take();
    app.settings_save_error.borrow_mut().take();
    // M6-UI — fold the saved accent into the live `theme_base_accent` so the
    // ringed swatch + zone accents reflect the persisted value, then clear the
    // in-flight draft (Save consumes it).
    if accent_clear_requested {
        *app.theme_base_accent.borrow_mut() = None;
    } else if let Some(accent) = accent_draft {
        *app.theme_base_accent.borrow_mut() = Some(accent);
    }
    app.settings_draft_accent_color.borrow_mut().take();
    app.settings_accent_clear_requested.set(false);
    true
}

/// M1a 2026-05-29 — discard pending General-section edits by replaying the
/// snapshot taken on `OpenSettings`. Called by Cancel, Escape, Close × and
/// click-outside dismissals so a dropped panel never leaks unflushed
/// toggles into the vault on next save. Idempotent when no snapshot
/// exists (first call clears it).
fn cancel_settings_general(root: &AppRoot) {
    let snapshot = {
        let app = root.app.borrow();
        let snapshot = app.settings_snapshot.borrow_mut().take();
        if let Some(snap) = snapshot.as_ref() {
            app.restore_settings(snap);
        }
        app.settings_dirty.set(false);
        app.settings_save_error.borrow_mut().take();
        // M6-UI — discard the in-flight §3 Appearance accent draft (Cancel reverts
        // the edit; the persisted `theme_base_accent` is untouched).
        app.settings_draft_accent_color.borrow_mut().take();
        app.settings_accent_clear_requested.set(false);
        // W-minor (#7 fix wave) — clear the focused-field caret on Cancel/Escape so
        // a stale focus/caret never leaks past the dismissal.
        app.settings_focused_field
            .set(bento_nano_app::SettingsTextField::None);
        snapshot
    };
    if let Some(snapshot) = snapshot {
        if let Err(error) = apply_active_theme_to_app(root, snapshot.active_theme_id.clone()) {
            tracing::warn!(
                target: "bentodesk::themes",
                theme_id = %snapshot.active_theme_id,
                %error,
                "Settings Cancel could not restore custom theme"
            );
        }
        request_theme_surface_redraw(root, false);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MinibarPinStateChange {
    Inserted,
    Refreshed,
}
const KEYBINDING_PREFIX: &str = "keybinding.";
const GLOBAL_HOTKEY_BASE_ID: i32 = 0x4240;

fn default_hotkey_bindings() -> smallvec::SmallVec<[hotkey::HotkeyBinding; 20]> {
    smallvec::SmallVec::from_slice(hotkey::DEFAULT_BINDINGS)
}

fn global_hotkey_id(command: hotkey::HotkeyCommand) -> Option<i32> {
    let offset = match command {
        hotkey::HotkeyCommand::Escape => return None,
        hotkey::HotkeyCommand::ToggleMain => 1,
        hotkey::HotkeyCommand::CreateZone => 2,
        hotkey::HotkeyCommand::DuplicateZone => 3,
        hotkey::HotkeyCommand::ToggleZoneLock => 4,
        hotkey::HotkeyCommand::ToggleAllZones => 5,
        hotkey::HotkeyCommand::AutoOrganize => 6,
        hotkey::HotkeyCommand::ReflowLayout => 7,
        hotkey::HotkeyCommand::OpenBulkManager => 8,
        hotkey::HotkeyCommand::FocusNextZone => 9,
        hotkey::HotkeyCommand::FocusPreviousZone => 10,
        hotkey::HotkeyCommand::ToggleSettings => 11,
        hotkey::HotkeyCommand::OpenSearch => 12,
        hotkey::HotkeyCommand::QuitApp => 13,
        hotkey::HotkeyCommand::OpenTimeline => 14,
        hotkey::HotkeyCommand::OpenSnapshotPicker => 15,
        hotkey::HotkeyCommand::UndoCheckpoint => 16,
        hotkey::HotkeyCommand::RedoCheckpoint => 17,
    };
    Some(GLOBAL_HOTKEY_BASE_ID + offset)
}

fn global_hotkey_modifiers(mods: hotkey::ModFlags) -> u32 {
    let mut flags = MOD_NOREPEAT;
    if mods.ctrl {
        flags |= MOD_CONTROL;
    }
    if mods.shift {
        flags |= MOD_SHIFT;
    }
    if mods.alt {
        flags |= MOD_ALT;
    }
    flags
}

fn global_hotkey_command(root: &AppRoot, id: i32) -> Option<hotkey::HotkeyCommand> {
    root.global_hotkeys
        .borrow()
        .iter()
        .find(|registration| registration.id == id)
        .map(|registration| registration.command)
}

unsafe fn unregister_global_hotkeys(root: &AppRoot, hwnd: HWND) {
    let mut registrations = root.global_hotkeys.borrow_mut();
    for registration in registrations.drain(..) {
        // SAFETY: `registration.id` was previously registered against this
        // Main HWND by `register_global_hotkeys`.
        let ok = unsafe { UnregisterHotKey(hwnd, registration.id) };
        if ok == 0 {
            tracing::warn!(
                target: "bentodesk::hotkey",
                id = registration.id,
                command = ?registration.command,
                error = unsafe { GetLastError() },
                "global hotkey unregister failed"
            );
        }
    }
}

unsafe fn register_global_hotkeys(root: &AppRoot, hwnd: HWND) -> usize {
    // SAFETY: Re-registration is Main-HWND scoped and starts by unregistering
    // every id known to have succeeded previously.
    unsafe { unregister_global_hotkeys(root, hwnd) };
    let bindings = root.hotkey_bindings.borrow();
    let mut registrations = root.global_hotkeys.borrow_mut();
    for binding in bindings.iter() {
        let Some(id) = global_hotkey_id(binding.command) else {
            continue;
        };
        let modifiers = global_hotkey_modifiers(binding.mods);
        // SAFETY: RegisterHotKey is called with the live Main HWND, an app
        // range id, Win32 modifier flags, and a virtual-key code from the
        // validated runtime table.
        let ok = unsafe { RegisterHotKey(hwnd, id, modifiers, binding.vk) };
        if ok == 0 {
            tracing::warn!(
                target: "bentodesk::hotkey",
                id,
                vk = binding.vk,
                modifiers,
                command = ?binding.command,
                error = unsafe { GetLastError() },
                "global hotkey registration failed; focused-HWND route remains available"
            );
            continue;
        }
        registrations.push(GlobalHotkeyRegistration {
            id,
            command: binding.command,
        });
    }
    let registered = registrations.len();
    log_static(format!("hotkey: registered_global count={registered}\n").as_str());
    registered
}

fn refresh_global_hotkeys(root: &AppRoot) -> bool {
    let Some(hwnd) = find_main_hwnd(root) else {
        return false;
    };
    // SAFETY: `hwnd` is the registered Main HWND owned by this process.
    unsafe { register_global_hotkeys(root, hwnd) > 0 }
}

fn apply_hotkey_binding(root: &AppRoot, action: &str, chord: &str) -> bool {
    let mut bindings = root.hotkey_bindings.borrow_mut();
    let binding = match hotkey::validate_binding(&bindings, action, chord) {
        Ok(binding) => binding,
        Err(hotkey::BindingValidationError::UnsupportedActionOrChord) => {
            tracing::warn!(
                target: "bentodesk::hotkey",
                %action,
                %chord,
                "keybinding rejected: unsupported action or chord"
            );
            return false;
        }
        Err(hotkey::BindingValidationError::ChordAlreadyAssigned) => {
            tracing::warn!(
                target: "bentodesk::hotkey",
                %action,
                %chord,
                "keybinding rejected: chord already assigned"
            );
            return false;
        }
    };
    if let Some(existing) = bindings
        .iter_mut()
        .find(|existing| existing.command == binding.command)
    {
        if existing.vk == binding.vk && existing.mods == binding.mods {
            return false;
        }
        *existing = binding;
        drop(bindings);
        let _ = refresh_global_hotkeys(root);
        return true;
    }
    bindings.push(binding);
    drop(bindings);
    let _ = refresh_global_hotkeys(root);
    true
}

fn apply_hotkey_setting_to_runtime(
    root: &AppRoot,
    key: &str,
    value: &bento_nano_app::SettingValue,
) -> bool {
    let Some(action) = key.strip_prefix(KEYBINDING_PREFIX) else {
        return false;
    };
    match value {
        bento_nano_app::SettingValue::Str(chord) => apply_hotkey_binding(root, action, chord),
        _ => {
            tracing::warn!(
                target: "bentodesk::hotkey",
                %key,
                "keybinding rejected: value must be a string chord"
            );
            false
        }
    }
}

fn keybinding_action_at(row_index: usize) -> Option<&'static str> {
    keybindings_section::keybinding_rows()
        .get(row_index)
        .map(|row| row.action)
}

fn keybinding_setting_key(action: &str) -> Option<SmolStr> {
    hotkey::command_for_action(action)?;
    Some(SmolStr::new(format!("{KEYBINDING_PREFIX}{action}")))
}

fn set_keybinding_feedback(app: &AppState, action: &str, message: SmolStr, is_error: bool) {
    let action = SmolStr::new(action);
    let feedback = if is_error {
        SettingsKeybindingFeedback::Error { action, message }
    } else {
        SettingsKeybindingFeedback::Success { action, message }
    };
    app.settings_keybinding_feedback
        .borrow_mut()
        .replace(feedback);
}

fn validate_keybinding_candidate(
    root: &AppRoot,
    action: &str,
    chord: &str,
) -> Result<(), hotkey::BindingValidationError> {
    let bindings = root.hotkey_bindings.borrow();
    hotkey::validate_binding(&bindings, action, chord).map(|_| ())
}

fn persist_keybinding_reset_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    action: &str,
) -> Result<bool, bento_nano_backend::config_vault::VaultError> {
    if vault.is_locked_passphrase() {
        return Err(bento_nano_backend::config_vault::VaultError::NoPassphraseSet);
    }
    let Some(key) = keybinding_setting_key(action) else {
        return Ok(false);
    };
    let removed = vault.remove_setting(key.as_str());
    if removed {
        vault.flush()?;
    }
    Ok(true)
}

fn queue_locale_setting_toggle(root: &AppRoot) {
    let next_locale = if bento_nano_style::current_locale_is(&bento_nano_style::ZH_CN) {
        "en-US"
    } else {
        "zh-CN"
    };
    root.dispatcher
        .push(locale_setting_command_for(next_locale));
    root.dispatcher.push(Command::ToggleLocale);
}

fn locale_setting_command_for(locale: &'static str) -> Command {
    Command::SetSetting {
        key: SmolStr::new_static(SETTING_DISPLAY_LOCALE),
        value: bento_nano_app::SettingValue::Str(SmolStr::new_static(locale)),
    }
}

fn queue_update_frequency_cycle(root: &AppRoot) {
    let next_frequency = {
        let app = root.app.borrow();
        next_update_frequency(app.update_check_frequency.get())
    };
    root.dispatcher
        .push(update_frequency_setting_command_for(next_frequency));
}

fn queue_update_auto_download_toggle(root: &AppRoot) {
    let next_value = {
        let app = root.app.borrow();
        !app.update_auto_download.get()
    };
    root.dispatcher.push(bool_setting_command_for(
        SETTING_UPDATES_AUTO_DOWNLOAD,
        next_value,
    ));
}

fn queue_update_action(root: &AppRoot) {
    let command = {
        let app = root.app.borrow();
        match &*app.settings_updater_status.borrow() {
            SettingsUpdaterStatus::Available { .. } => Some(Command::DownloadUpdate),
            SettingsUpdaterStatus::Ready { .. } => Some(Command::InstallUpdateAndRestart),
            _ => None,
        }
    };
    if let Some(command) = command {
        root.dispatcher.push(command);
    } else {
        let app = root.app.borrow();
        *app.settings_updater_status.borrow_mut() =
            SettingsUpdaterStatus::Error(SmolStr::new_static("No update action is available"));
    }
}

fn queue_update_skip(root: &AppRoot, hwnd: HWND) {
    let version = {
        let app = root.app.borrow();
        app.settings_updater_status.borrow().version_for_skip()
    };
    match version {
        Some(version) => {
            root.dispatcher.push(Command::SkipUpdateVersion(version));
        }
        None => {
            let app = root.app.borrow();
            *app.settings_updater_status.borrow_mut() = SettingsUpdaterStatus::Error(
                SmolStr::new_static("No update version is available to skip"),
            );
            request_redraw(hwnd);
        }
    }
}

fn queue_stealth_enabled_toggle(root: &AppRoot) {
    let next_value = {
        let app = root.app.borrow();
        !app.stealth_enabled.get()
    };
    root.dispatcher.push(bool_setting_command_for(
        SETTING_STEALTH_ENABLED,
        next_value,
    ));
}

// M7 (2026-06-01) — `queue_encryption_mode_cycle` removed. The orphan
// `CycleEncryptionMode` 2-cycle (None↔Dpapi, Passphrase→None) was replaced
// wholesale by the §10 3-button mode grid; its passphrase-capture-activation
// snippet moved into the `SelectEncryptionModePassphrase` / `FocusPassphraseField`
// dispatch arms, and the direct None/Dpapi sets now route through the existing
// `encryption_mode_setting_command_for` helper from the mode-button arms.

// Wave J1b — kept for future keyboard / tray cycle paths even though the
// Row 5 chip now toggles the swatch popup instead of cycling inline.
#[allow(dead_code)]
fn queue_active_theme_cycle(root: &AppRoot, hwnd: HWND) {
    match apply_available_themes_to_app(root) {
        Ok(changed) => {
            if changed && !hwnd.is_null() {
                request_redraw(hwnd);
            }
        }
        Err(error) => {
            set_theme_setting_error(root, SmolStr::new(format!("Theme list failed: {error}")));
            if !hwnd.is_null() {
                request_redraw(hwnd);
            }
            return;
        }
    }
    let (current_id, themes) = {
        let app = root.app.borrow();
        (
            app.active_theme_id.borrow().clone(),
            app.available_themes.borrow().clone(),
        )
    };
    if themes.is_empty() {
        set_theme_setting_error(root, SmolStr::new_static(no_themes_available_message()));
        request_redraw(hwnd);
        return;
    }
    let current_index = themes
        .iter()
        .position(|theme| theme.id == current_id)
        .unwrap_or(themes.len().saturating_sub(1));
    let next_index = (current_index + 1) % themes.len();
    if let Some(next) = themes.get(next_index) {
        root.dispatcher
            .push(Command::SetActiveTheme(next.id.clone()));
    }
}

// M6-UI (2026-05-29) — the Wave J1b popup picker→backend mapping table
// (`PICKER_TO_BACKEND`) and its three lookup helpers
// (`backend_theme_id_for_picker_index` / `picker_index_for_backend_id` /
// `picker_preset_display_name`) were removed: §3 Appearance is now the inline
// grid. Each ThemeCard carries its own stable `theme_id`
// (`theme_picker::BUILTIN_THEMES[i].theme_id`) which routes straight through
// M6a's `apply_active_theme_by_id` (all 17 builtins, no partial-preview
// fallback), so no index→id translation table is needed.

fn queue_zone_display_mode_cycle(root: &AppRoot) {
    let app = root.app.borrow();
    let next_mode = app.zone_display_mode.get().next();
    app.set_zone_display_mode(next_mode);
    app.settings_dirty.set(true);
    app.settings_save_error.borrow_mut().take();
}

/// α4 (Wave I-α, 2026-05-25) — dispatch `Command::SetSetting` with an
/// explicit zone-display mode chosen from the 3-radio picker (instead of
/// cycling). Mirrors `queue_zone_display_mode_cycle` byte-for-byte except
/// for the source of `next_mode`.
fn queue_zone_display_mode_set(root: &AppRoot, mode: bento_nano_app::ZoneDisplayMode) {
    let app = root.app.borrow();
    app.set_zone_display_mode(mode);
    app.settings_dirty.set(true);
    app.settings_save_error.borrow_mut().take();
}

