fn persist_skipped_update_to_vault(version: &SmolStr) {
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        tracing::warn!(
            target: "bentodesk::updater",
            version = %version,
            "SkipUpdateVersion: vault not initialised; skip remains in memory only"
        );
        return;
    };
    match mtx.lock() {
        Ok(mut vault) => {
            if vault.is_locked_passphrase() {
                tracing::warn!(
                    target: "bentodesk::updater",
                    version = %version,
                    "SkipUpdateVersion: vault locked; skip remains in memory only"
                );
                return;
            }
            vault.set_setting(
                SETTING_UPDATES_SKIPPED_VERSION,
                bento_nano_backend::config_vault::SettingValue::Str(version.clone()),
            );
            if let Err(error) = vault.flush() {
                tracing::warn!(
                    target: "bentodesk::updater",
                    version = %version,
                    error = %error,
                    "SkipUpdateVersion: flush failed; skip remains in memory only"
                );
            }
        }
        Err(_poisoned) => {
            tracing::warn!(
                target: "bentodesk::updater",
                version = %version,
                "SkipUpdateVersion: vault mutex poisoned; skip remains in memory only"
            );
        }
    }
}

fn current_minibar_pins_csv(root: &AppRoot) -> Option<SmolStr> {
    let app = root.app.borrow();
    let minibars = app.minibars.borrow();
    let mut csv = String::new();
    for (zone_id, _) in minibars.iter() {
        if !csv.is_empty() {
            csv.push(',');
        }
        let _ = core::fmt::Write::write_fmt(&mut csv, format_args!("{}", zone_id.0));
    }
    if csv.is_empty() {
        None
    } else {
        Some(SmolStr::new(csv))
    }
}

fn list_pinned_minibar_labels(
    root: &AppRoot,
) -> smallvec::SmallVec<[SmolStr; BUSINESS_MAX_MINIBARS]> {
    let app = root.app.borrow();
    app.minibars
        .borrow()
        .iter()
        .map(|(zone_id, _bar)| SmolStr::new(format!("minibar-{}", zone_id.0)))
        .collect()
}

fn show_pinned_minibar_list_status(root: &AppRoot) {
    let labels = list_pinned_minibar_labels(root);
    if labels.is_empty() {
        set_item_operation_status(root, SmolStr::new_static("No pinned minibars"));
        log_static("minibar: ListPinnedMinibars status=No pinned minibars\n");
        return;
    }
    let mut status = String::from("Pinned minibars: ");
    for (index, label) in labels.iter().enumerate() {
        if index > 0 {
            status.push_str(", ");
        }
        status.push_str(label.as_str());
    }
    log_static(format!("minibar: ListPinnedMinibars status={status}\n").as_str());
    set_item_operation_status(root, SmolStr::new(status));
}

fn write_minibar_pins_to_vault(
    root: &AppRoot,
    vault: &mut bento_nano_backend::config_vault::Vault,
) {
    match current_minibar_pins_csv(root) {
        Some(value) => vault.set_setting(
            SETTING_MINIBAR_PINNED_ZONES,
            bento_nano_backend::config_vault::SettingValue::Str(value),
        ),
        None => {
            let _ = vault.remove_setting(SETTING_MINIBAR_PINNED_ZONES);
        }
    }
}

fn parse_minibar_pin_ids(value: &str) -> smallvec::SmallVec<[ZoneId; BUSINESS_MAX_MINIBARS]> {
    let mut ids = smallvec::SmallVec::<[ZoneId; BUSINESS_MAX_MINIBARS]>::new();
    for raw in value.split(',') {
        if ids.len() >= BUSINESS_MAX_MINIBARS {
            break;
        }
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            continue;
        }
        let Ok(id) = trimmed.parse::<u64>() else {
            tracing::warn!(
                target: "bentodesk::minibar",
                value = trimmed,
                "minibar.pinned_zones restore skipped: invalid zone id"
            );
            continue;
        };
        let zone_id = ZoneId(id);
        if zone_id == ZoneId::INVALID || ids.contains(&zone_id) {
            continue;
        }
        ids.push(zone_id);
    }
    ids
}

fn restore_minibar_pins_from_wire_value<F>(root: &AppRoot, value: &str, mut pin_zone: F) -> usize
where
    F: FnMut(&AppRoot, ZoneId) -> bool,
{
    let mut restored = 0usize;
    for zone_id in parse_minibar_pin_ids(value) {
        if pin_zone(root, zone_id) {
            restored += 1;
        }
    }
    restored
}

fn persist_minibar_pins_to_vault(root: &AppRoot) {
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        tracing::warn!(
            target: "bentodesk::minibar",
            "minibar pins not persisted: vault not initialised"
        );
        return;
    };
    match mtx.lock() {
        Ok(mut vault) => {
            if vault.is_locked_passphrase() {
                tracing::warn!(
                    target: "bentodesk::minibar",
                    "minibar pins not persisted: vault locked"
                );
                return;
            }
            write_minibar_pins_to_vault(root, &mut vault);
            if let Err(error) = vault.flush() {
                tracing::warn!(
                    target: "bentodesk::minibar",
                    error = %error,
                    "minibar pins flush failed"
                );
            }
        }
        Err(_poisoned) => {
            tracing::warn!(
                target: "bentodesk::minibar",
                "minibar pins not persisted: vault mutex poisoned"
            );
        }
    }
}

fn restore_persisted_minibars_from_vault(root: &AppRoot) {
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        return;
    };
    let setting = match mtx.lock() {
        Ok(vault) if vault.is_locked_passphrase() => return,
        Ok(vault) => vault.get_setting(SETTING_MINIBAR_PINNED_ZONES),
        Err(_poisoned) => {
            tracing::warn!(
                target: "bentodesk::minibar",
                "minibar restore skipped: vault mutex poisoned"
            );
            return;
        }
    };
    match setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(value)) => {
            let _ = restore_minibar_pins_from_wire_value(root, value.as_str(), pin_zone_as_minibar);
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::minibar",
                "minibar.pinned_zones restore skipped: non-string setting"
            );
        }
        None => {}
    }
}

fn apply_persisted_settings_from_vault(root: &AppRoot) {
    if let Err(error) = apply_available_themes_to_app(root) {
        set_theme_setting_error(
            root,
            SmolStr::new(format!("Theme list restore failed: {error}")),
        );
    }
    let Some(mtx) = bento_nano_backend::config_vault::Vault::global() else {
        return;
    };
    let Ok(vault) = mtx.lock() else {
        tracing::warn!(
            target: "bentodesk::vault",
            "settings restore skipped: vault mutex poisoned"
        );
        return;
    };
    let locale_setting = vault.get_setting(SETTING_DISPLAY_LOCALE);
    let update_frequency_setting = vault.get_setting(SETTING_UPDATES_CHECK_FREQUENCY);
    let update_auto_download_setting = vault.get_setting(SETTING_UPDATES_AUTO_DOWNLOAD);
    let update_skipped_version_setting = vault.get_setting(SETTING_UPDATES_SKIPPED_VERSION);
    let stealth_enabled_setting = vault.get_setting(SETTING_STEALTH_ENABLED);
    let encryption_mode_setting = vault.get_setting(SETTING_ENCRYPTION_MODE);
    let theme_base_accent_setting = vault.get_setting(SETTING_THEME_BASE_ACCENT);
    let active_theme_setting = vault.get_setting(SETTING_ACTIVE_THEME);
    let zone_display_mode_setting = vault.get_setting(SETTING_ZONE_DISPLAY_MODE);
    let debug_overlay_setting = vault.get_setting(SETTING_DEBUG_OVERLAY);
    let keybinding_settings = hotkey::HOTKEY_ACTIONS
        .iter()
        .filter_map(|action| {
            let key = format!("{KEYBINDING_PREFIX}{action}");
            match vault.get_setting(&key) {
                Some(bento_nano_backend::config_vault::SettingValue::Str(chord)) => {
                    Some((*action, chord))
                }
                Some(_) => {
                    tracing::warn!(
                        target: "bentodesk::hotkey",
                        %key,
                        "keybinding restore skipped: non-string setting"
                    );
                    None
                }
                None => None,
            }
        })
        .collect::<smallvec::SmallVec<[(&'static str, SmolStr); 8]>>();
    let vault_is_locked_passphrase = vault.is_locked_passphrase();
    drop(vault);

    if vault_is_locked_passphrase {
        let app = root.app.borrow();
        app.encryption_mode.set(SettingsEncryptionMode::Passphrase);
        app.passphrase_unlock_required.set(true);
        app.settings_encryption_status
            .borrow_mut()
            .replace(SettingsBackupStatus::Error(SmolStr::new_static(
                "Passphrase unlock required",
            )));
        return;
    }

    for (action, chord) in keybinding_settings {
        let _ = apply_hotkey_binding(root, action, chord.as_str());
    }

    match locale_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(locale)) => {
            if !apply_locale_wire(locale.as_str()) {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %locale,
                    "display.locale restore skipped: unsupported locale value"
                );
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "display.locale restore skipped: non-string setting"
            );
        }
        None => {}
    }

    let app = root.app.borrow();
    app.passphrase_unlock_required.set(false);
    match update_frequency_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(frequency)) => {
            if let Some(parsed) = update_frequency_from_wire(frequency.as_str()) {
                app.update_check_frequency.set(parsed);
            } else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %frequency,
                    "updates.check_frequency restore skipped: unsupported value"
                );
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "updates.check_frequency restore skipped: non-string setting"
            );
        }
        None => {}
    }
    match update_auto_download_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Bool(value)) => {
            app.update_auto_download.set(value);
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "updates.auto_download restore skipped: non-bool setting"
            );
        }
        None => {}
    }
    match update_skipped_version_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(version)) => {
            root.updater.skip_version(version.clone());
            *app.settings_updater_status.borrow_mut() = SettingsUpdaterStatus::Skipped { version };
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "updates.skipped_version restore skipped: non-string setting"
            );
        }
        None => {}
    }
    match stealth_enabled_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Bool(value)) => {
            app.stealth_enabled.set(value);
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "stealth.enabled restore skipped: non-bool setting"
            );
        }
        None => {}
    }
    match debug_overlay_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Bool(value)) => {
            app.debug_overlay.borrow_mut().visible = value;
            log_static(format!("debug_overlay: restored persisted visible={value}\n").as_str());
            tracing::info!(
                target: "bentodesk::debug_overlay",
                "debug_overlay: restored persisted visible={}",
                value
            );
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "debug_overlay restore skipped: non-bool setting"
            );
        }
        None => {}
    }
    match encryption_mode_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(mode)) => {
            if let Some(parsed) = encryption_mode_from_wire(mode.as_str()) {
                app.encryption_mode.set(parsed);
            } else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %mode,
                    "encryption.mode restore skipped: unsupported or deferred value"
                );
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "encryption.mode restore skipped: non-string setting"
            );
        }
        None => {}
    }
    match theme_base_accent_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(accent)) => {
            if let Some(parsed) = theme_base_accent_from_wire(accent.as_str()) {
                let _changed = apply_theme_base_accent_to_app(&app, Some(parsed));
            } else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %accent,
                    "theme.base_accent restore skipped: unsupported palette swatch"
                );
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "theme.base_accent restore skipped: non-string setting"
            );
        }
        None => {}
    }
    match zone_display_mode_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(mode)) => {
            if let Some(parsed) = zone_display_mode_from_wire(mode.as_str()) {
                app.zone_display_mode.set(parsed);
                log_static(format!("zone_display_mode restored: {}\n", parsed.as_wire()).as_str());
            } else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %mode,
                    "zone_display_mode restore skipped: unsupported value"
                );
                app.settings_theme_status
                    .borrow_mut()
                    .replace(SettingsBackupStatus::Error(SmolStr::new(format!(
                        "Display mode ignored: {mode}"
                    ))));
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "zone_display_mode restore skipped: non-string setting"
            );
        }
        None => {}
    }
    drop(app);
    match active_theme_setting {
        Some(bento_nano_backend::config_vault::SettingValue::Str(theme_id)) => {
            if let Err(error) = apply_active_theme_to_app(root, theme_id.clone()) {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %theme_id,
                    error = %error,
                    "active_theme restore skipped"
                );
                set_theme_setting_error(root, SmolStr::new(format!("Theme ignored: {theme_id}")));
            }
        }
        Some(_) => {
            tracing::warn!(
                target: "bentodesk::vault",
                "active_theme restore skipped: non-string setting"
            );
        }
        None => {}
    }
    // M1a 2026-05-29 — restore the 5 General-section toggles from the
    // vault. Calling this AFTER the locale / updater / theme branches keeps
    // the warn-on-poisoned-vault flow consistent with the existing reads
    // and lets a partial-failure (e.g., missing keys) fall through to the
    // AppState defaults defined in `AppState::new`.
    apply_general_settings_from_vault(&root.app.borrow());
}

fn apply_locale_wire(locale: &str) -> bool {
    match locale {
        "en-US" => {
            bento_nano_style::set_locale(&bento_nano_style::EN_US);
            true
        }
        "zh-CN" => {
            bento_nano_style::set_locale(&bento_nano_style::ZH_CN);
            true
        }
        _ => false,
    }
}

fn apply_setting_value_to_app(
    app: &AppState,
    key: &str,
    value: &bento_nano_app::SettingValue,
) -> bool {
    match (key, value) {
        (SETTING_UPDATES_CHECK_FREQUENCY, bento_nano_app::SettingValue::Str(frequency)) => {
            let Some(parsed) = update_frequency_from_wire(frequency.as_str()) else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %frequency,
                    "updates.check_frequency rejected: unsupported value"
                );
                return false;
            };
            let changed = app.update_check_frequency.get() != parsed;
            app.update_check_frequency.set(parsed);
            changed
        }
        (SETTING_UPDATES_AUTO_DOWNLOAD, bento_nano_app::SettingValue::Bool(value)) => {
            let changed = app.update_auto_download.get() != *value;
            app.update_auto_download.set(*value);
            changed
        }
        (SETTING_STEALTH_ENABLED, bento_nano_app::SettingValue::Bool(value)) => {
            let changed = app.stealth_enabled.get() != *value;
            app.stealth_enabled.set(*value);
            changed
        }
        (SETTING_DEBUG_OVERLAY, bento_nano_app::SettingValue::Bool(value)) => {
            let mut overlay = app.debug_overlay.borrow_mut();
            let changed = overlay.visible != *value;
            overlay.visible = *value;
            changed
        }
        (SETTING_ENCRYPTION_MODE, bento_nano_app::SettingValue::Str(mode)) => {
            let Some(parsed) = encryption_mode_from_wire(mode.as_str()) else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %mode,
                    "encryption.mode rejected: unsupported or deferred value"
                );
                return false;
            };
            if parsed == SettingsEncryptionMode::Passphrase {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %mode,
                    "encryption.mode rejected: Passphrase requires dedicated command"
                );
                return false;
            }
            let changed = app.encryption_mode.get() != parsed;
            app.encryption_mode.set(parsed);
            changed
        }
        (SETTING_ZONE_DISPLAY_MODE, bento_nano_app::SettingValue::Str(mode)) => {
            let Some(parsed) = zone_display_mode_from_wire(mode.as_str()) else {
                tracing::warn!(
                    target: "bentodesk::vault",
                    %mode,
                    "zone_display_mode rejected: unsupported value"
                );
                app.settings_theme_status
                    .borrow_mut()
                    .replace(SettingsBackupStatus::Error(SmolStr::new(format!(
                        "Display mode rejected: {mode}"
                    ))));
                return false;
            };
            let changed = app.set_zone_display_mode(parsed);
            app.settings_theme_status
                .borrow_mut()
                .replace(SettingsBackupStatus::Success(SmolStr::new(format!(
                    "Mode {}",
                    parsed.label()
                ))));
            changed
        }
        _ => false,
    }
}

fn apply_update_event_to_app(app: &AppState, event: UpdateEvent) {
    let next_status = match event {
        UpdateEvent::Available { info } => SettingsUpdaterStatus::Available {
            version: info.version,
        },
        UpdateEvent::Progress { progress } => SettingsUpdaterStatus::Downloading {
            chunk_len: progress.chunk_len,
            total_bytes: progress.total_bytes,
        },
        UpdateEvent::Ready { info } => SettingsUpdaterStatus::Ready {
            version: info.version,
        },
        UpdateEvent::Installing { info } => SettingsUpdaterStatus::Installing {
            version: info.version,
        },
        UpdateEvent::Error { kind, message } => {
            SettingsUpdaterStatus::Error(SmolStr::new(format!("{kind}: {message}")))
        }
    };
    *app.settings_updater_status.borrow_mut() = next_status;
}

fn updater_event_should_auto_download(app: &AppState, event: &UpdateEvent) -> bool {
    app.update_auto_download.get() && matches!(event, UpdateEvent::Available { .. })
}

fn set_update_error(app: &AppState, action: &str, error: &dyn core::fmt::Display) {
    *app.settings_updater_status.borrow_mut() =
        SettingsUpdaterStatus::Error(SmolStr::new(format!("{action}: {error}")));
}

fn persist_setting_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    key: &str,
    value: &bento_nano_app::SettingValue,
) -> Result<bool, bento_nano_backend::config_vault::VaultError> {
    if vault.is_locked_passphrase() {
        return Err(bento_nano_backend::config_vault::VaultError::NoPassphraseSet);
    }
    let backend_value = backend_setting_value_from_app(value);
    if key == SETTING_ENCRYPTION_MODE {
        let Some(mode) = (match value {
            bento_nano_app::SettingValue::Str(mode) => encryption_mode_from_wire(mode.as_str()),
            _ => None,
        }) else {
            tracing::warn!(
                target: "bentodesk::vault",
                %key,
                "SetSetting rejected: encryption.mode requires None/Dpapi/Passphrase string"
            );
            return Ok(false);
        };
        if mode == SettingsEncryptionMode::Passphrase {
            tracing::warn!(
                target: "bentodesk::vault",
                %key,
                "SetSetting rejected: Passphrase requires SetEncryptionPassphrase"
            );
            return Ok(false);
        }
        vault.set_setting(key, backend_value);
        vault.set_mode(backend_encryption_mode_from_app(mode))?;
        vault.flush()?;
        return Ok(true);
    }
    if key == SETTING_ZONE_DISPLAY_MODE {
        let Some(mode) = (match value {
            bento_nano_app::SettingValue::Str(mode) => zone_display_mode_from_wire(mode.as_str()),
            _ => None,
        }) else {
            tracing::warn!(
                target: "bentodesk::vault",
                %key,
                "SetSetting rejected: zone_display_mode requires hover/always/click string"
            );
            return Ok(false);
        };
        return persist_zone_display_mode_to_vault(vault, mode);
    }

    vault.set_setting(key, backend_value);
    vault.flush()?;
    Ok(true)
}

fn persist_passphrase_to_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    passphrase: &str,
) -> Result<(), bento_nano_backend::config_vault::VaultError> {
    vault.set_setting(
        SETTING_ENCRYPTION_MODE,
        bento_nano_backend::config_vault::SettingValue::Str(SmolStr::new_static("Passphrase")),
    );
    vault.set_mode(
        bento_nano_backend::config_vault::EncryptionMode::Passphrase {
            passphrase: SmolStr::new(passphrase),
        },
    )?;
    vault.flush()?;
    let reopened =
        bento_nano_backend::config_vault::Vault::open_with_passphrase(vault.path(), passphrase)?;
    *vault = reopened;
    Ok(())
}

fn unlock_passphrase_vault(
    vault: &mut bento_nano_backend::config_vault::Vault,
    passphrase: &str,
) -> Result<(), bento_nano_backend::config_vault::VaultError> {
    let reopened =
        bento_nano_backend::config_vault::Vault::open_with_passphrase(vault.path(), passphrase)?;
    *vault = reopened;
    Ok(())
}

#[derive(Debug)]
enum ContextCapsuleError {
    MissingZonesParent,
    EmptyCapsuleId,
    CapsuleNotFound(SmolStr),
    InvalidEnvelope(SmolStr),
    Codec(PlatformError),
    Base64(bento_nano_backend::config_vault::wire::Base64Error),
    Json(serde_json::Error),
    Io {
        op: &'static str,
        path: PathBuf,
        source: std::io::Error,
    },
}

impl core::fmt::Display for ContextCapsuleError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::MissingZonesParent => f.write_str("zones path has no parent directory"),
            Self::EmptyCapsuleId => f.write_str("context capsule id is empty"),
            Self::CapsuleNotFound(capsule_id) => {
                write!(f, "context capsule not found: {capsule_id}")
            }
            Self::InvalidEnvelope(message) => {
                write!(f, "context capsule envelope invalid: {message}")
            }
            Self::Codec(source) => write!(f, "context capsule payload invalid: {source}"),
            Self::Base64(source) => write!(f, "context capsule base64 invalid: {source}"),
            Self::Json(source) => write!(f, "context capsule json invalid: {source}"),
            Self::Io { op, path, source } => {
                write!(f, "{op} failed at {}: {source}", path.display())
            }
        }
    }
}

impl core::error::Error for ContextCapsuleError {}

impl From<PlatformError> for ContextCapsuleError {
    fn from(value: PlatformError) -> Self {
        Self::Codec(value)
    }
}

impl From<bento_nano_backend::config_vault::wire::Base64Error> for ContextCapsuleError {
    fn from(value: bento_nano_backend::config_vault::wire::Base64Error) -> Self {
        Self::Base64(value)
    }
}

impl From<serde_json::Error> for ContextCapsuleError {
    fn from(value: serde_json::Error) -> Self {
        Self::Json(value)
    }
}

#[derive(Debug)]
struct ContextCapsuleCandidate {
    path: PathBuf,
    entry: CapsuleEntry,
    modified: SystemTime,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ContextCapsuleWindow {
    title: String,
    class_name: String,
    process_name: String,
    rect: (i32, i32, i32, i32),
    is_maximized: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ContextCapsuleEnvelope {
    schema: u32,
    name: String,
    icon: String,
    captured_at: String,
    zones_codec: String,
    zones_bin_b64: String,
    windows: Vec<ContextCapsuleWindow>,
}

#[derive(Debug, Clone)]
struct LiveContextWindow {
    hwnd: HWND,
    title: String,
    class_name: String,
    process_name: String,
    rect: (i32, i32, i32, i32),
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ContextWindowRestoreReport {
    restored: usize,
    pending: usize,
    errors: usize,
}

const CONTEXT_CAPSULE_SCHEMA: u32 = 2;
const CONTEXT_CAPSULE_ZONES_CODEC: &str = "bento-nano-zones-bin-v1";
const CONTEXT_CAPSULE_FILE_PREFIX: &str = "capsule-";
const CONTEXT_CAPSULE_FILE_SUFFIX: &str = ".bin";
const CONTEXT_WINDOW_MIN_SIZE: i32 = 50;

fn context_capsule_dir_for_zones_path(zones_path: &Path) -> Result<PathBuf, ContextCapsuleError> {
    let Some(parent) = zones_path.parent() else {
        return Err(ContextCapsuleError::MissingZonesParent);
    };
    Ok(parent.join("capsules"))
}

fn context_capsule_file_name(capsule_id: &str) -> String {
    format!("{CONTEXT_CAPSULE_FILE_PREFIX}{capsule_id}{CONTEXT_CAPSULE_FILE_SUFFIX}")
}

fn context_capsule_id_from_file_name(file_name: &str) -> Option<&str> {
    file_name
        .strip_prefix(CONTEXT_CAPSULE_FILE_PREFIX)
        .and_then(|value| value.strip_suffix(CONTEXT_CAPSULE_FILE_SUFFIX))
        .filter(|value| !value.is_empty())
}

fn sanitize_context_capsule_name(name: &str) -> SmolStr {
    let trimmed = name.trim();
    let source = if trimmed.is_empty() {
        "Context Capsule"
    } else {
        trimmed
    };
    let mut output = String::with_capacity(source.len().min(80));
    let mut last_dash = false;
    for (char_index, ch) in source.chars().enumerate() {
        if char_index >= 48 {
            break;
        }
        let invalid =
            ch.is_control() || matches!(ch, '<' | '>' | ':' | '"' | '/' | '\\' | '|' | '?' | '*');
        if invalid || ch.is_whitespace() {
            if !last_dash {
                output.push('-');
                last_dash = true;
            }
        } else {
            output.push(ch);
            last_dash = false;
        }
    }
    let sanitized = output.trim_matches('-');
    if sanitized.is_empty() {
        SmolStr::new_static("Context-Capsule")
    } else {
        SmolStr::new(sanitized)
    }
}

fn display_name_from_context_capsule_id(capsule_id: &str) -> SmolStr {
    let name_segment = capsule_id.splitn(4, '-').nth(3).unwrap_or(capsule_id);
    let mut output = String::with_capacity(name_segment.len());
    let mut last_space = false;
    for ch in name_segment.chars() {
        if matches!(ch, '-' | '_') {
            if !last_space {
                output.push(' ');
                last_space = true;
            }
        } else {
            output.push(ch);
            last_space = false;
        }
    }
    let display = output.trim();
    if display.is_empty() {
        SmolStr::new_static(context_menu_text("场景胶囊", "Context Capsule"))
    } else {
        SmolStr::new(display)
    }
}

fn default_context_capsule_name() -> SmolStr {
    SmolStr::new(format!(
        "{} {}",
        context_menu_text("场景胶囊", "Context Capsule"),
        bento_nano_backend::time::now_compact_rfc3339()
    ))
}

fn new_context_capsule_id(name: &str) -> SmolStr {
    let stamp = bento_nano_backend::time::now_compact_rfc3339();
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |duration| duration.subsec_nanos());
    let safe_name = sanitize_context_capsule_name(name);
    SmolStr::new(format!(
        "{stamp}-{:x}-{nanos:08x}-{safe_name}",
        std::process::id()
    ))
}

fn context_capsule_payload_is_json(payload: &[u8]) -> bool {
    payload
        .iter()
        .copied()
        .find(|byte| !byte.is_ascii_whitespace())
        == Some(b'{')
}

fn encode_context_capsule_envelope(
    zones: &ZoneList,
    name: &str,
    windows: Vec<ContextCapsuleWindow>,
) -> Result<Vec<u8>, ContextCapsuleError> {
    let envelope = ContextCapsuleEnvelope {
        schema: CONTEXT_CAPSULE_SCHEMA,
        name: name.trim().to_owned(),
        icon: "briefcase".to_owned(),
        captured_at: bento_nano_backend::time::now_rfc3339(),
        zones_codec: CONTEXT_CAPSULE_ZONES_CODEC.to_owned(),
        zones_bin_b64: bento_nano_backend::config_vault::wire::base64_encode(&storage::encode(
            zones,
        )),
        windows,
    };
    serde_json::to_vec_pretty(&envelope).map_err(ContextCapsuleError::Json)
}

fn decode_context_capsule_envelope(
    payload: &[u8],
) -> Result<ContextCapsuleEnvelope, ContextCapsuleError> {
    let envelope: ContextCapsuleEnvelope = serde_json::from_slice(payload)?;
    if envelope.schema != CONTEXT_CAPSULE_SCHEMA {
        return Err(ContextCapsuleError::InvalidEnvelope(SmolStr::new(format!(
            "unsupported schema {}",
            envelope.schema
        ))));
    }
    if envelope.zones_codec != CONTEXT_CAPSULE_ZONES_CODEC {
        return Err(ContextCapsuleError::InvalidEnvelope(SmolStr::new(format!(
            "unsupported zones codec {}",
            envelope.zones_codec
        ))));
    }
    Ok(envelope)
}

fn envelope_entry_from_payload(
    capsule_id: SmolStr,
    fallback_modified: SystemTime,
    payload: &[u8],
) -> CapsuleEntry {
    if context_capsule_payload_is_json(payload) {
        if let Ok(envelope) = decode_context_capsule_envelope(payload) {
            return CapsuleEntry::new(
                capsule_id,
                SmolStr::new(envelope.name),
                SmolStr::new(envelope.icon),
                envelope.captured_at,
            );
        }
    }
    CapsuleEntry::new(
        capsule_id.clone(),
        display_name_from_context_capsule_id(capsule_id.as_str()),
        "archive",
        bento_nano_backend::time::system_time_to_rfc3339(fallback_modified),
    )
}

fn decode_context_capsule_zones(payload: &[u8]) -> Result<ZoneList, ContextCapsuleError> {
    if !context_capsule_payload_is_json(payload) {
        return Ok(storage::decode(payload)?);
    }
    let envelope = decode_context_capsule_envelope(payload)?;
    let zones_payload =
        bento_nano_backend::config_vault::wire::base64_decode(&envelope.zones_bin_b64)?;
    let zones = storage::decode(&zones_payload)?;
    let report = restore_captured_context_windows(&envelope.windows);
    log_static(
        format!(
            "capsule: restore window report name={} total={} restored={} pending={} errors={}\n",
            envelope.name,
            envelope.windows.len(),
            report.restored,
            report.pending,
            report.errors
        )
        .as_str(),
    );
    tracing::info!(
        target: "bentodesk::context_capsule",
        capsule_name = %envelope.name,
        windows_total = envelope.windows.len(),
        windows_restored = report.restored,
        windows_pending = report.pending,
        windows_errors = report.errors,
        "restored selected-stack context capsule envelope"
    );
    Ok(zones)
}

fn class_is_context_capsule_excluded(class_name: &str) -> bool {
    const BLACKLIST: &[&str] = &[
        "Progman",
        "WorkerW",
        "Shell_TrayWnd",
        "Shell_SecondaryTrayWnd",
        "Button",
        "NotifyIconOverflowWindow",
        "Windows.UI.Core.CoreWindow",
        "ApplicationFrameWindow",
        "Bento",
    ];
    BLACKLIST.iter().any(|needle| class_name.contains(needle))
}

fn read_window_text(hwnd: HWND) -> Option<String> {
    let len = unsafe { GetWindowTextLengthW(hwnd) };
    if len <= 0 {
        return None;
    }
    let mut buffer = vec![0u16; len as usize + 1];
    let copied = unsafe { GetWindowTextW(hwnd, buffer.as_mut_ptr(), buffer.len() as i32) };
    if copied <= 0 {
        return None;
    }
    let title = String::from_utf16_lossy(&buffer[..copied as usize]);
    let title = title.trim();
    if title.is_empty() {
        None
    } else {
        Some(title.to_owned())
    }
}

fn read_window_class(hwnd: HWND) -> Option<String> {
    let mut buffer = [0u16; 256];
    let copied = unsafe { GetClassNameW(hwnd, buffer.as_mut_ptr(), buffer.len() as i32) };
    if copied <= 0 {
        return None;
    }
    Some(String::from_utf16_lossy(&buffer[..copied as usize]))
}

fn lookup_context_process_name(pid: u32) -> String {
    if pid == 0 {
        return String::new();
    }
    let handle = unsafe { OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, pid) };
    if handle.is_null() {
        return String::new();
    }
    let mut buffer = [0u16; 260];
    let copied = unsafe {
        GetModuleFileNameExW(
            handle,
            ptr::null_mut(),
            buffer.as_mut_ptr(),
            buffer.len() as u32,
        )
    };
    unsafe {
        CloseHandle(handle);
    }
    if copied == 0 {
        return String::new();
    }
    let full = String::from_utf16_lossy(&buffer[..copied as usize]);
    full.rsplit(['\\', '/']).next().unwrap_or(&full).to_owned()
}

fn enumerate_live_context_windows() -> Vec<LiveContextWindow> {
    let mut windows = Vec::<LiveContextWindow>::new();
    let lparam = &mut windows as *mut Vec<LiveContextWindow> as LPARAM;
    unsafe {
        EnumWindows(Some(enum_context_window_proc), lparam);
    }
    windows
}

unsafe extern "system" fn enum_context_window_proc(hwnd: HWND, lparam: LPARAM) -> BOOL {
    let out = unsafe { &mut *(lparam as *mut Vec<LiveContextWindow>) };
    if unsafe { IsWindowVisible(hwnd) } == 0 || unsafe { IsIconic(hwnd) } != 0 {
        return 1;
    }
    let Some(title) = read_window_text(hwnd) else {
        return 1;
    };
    let Some(class_name) = read_window_class(hwnd) else {
        return 1;
    };
    if class_is_context_capsule_excluded(&class_name) {
        return 1;
    }
    let mut rect = RECT {
        left: 0,
        top: 0,
        right: 0,
        bottom: 0,
    };
    if unsafe { GetWindowRect(hwnd, &mut rect) } == 0 {
        return 1;
    }
    let mut pid = 0u32;
    unsafe {
        GetWindowThreadProcessId(hwnd, &mut pid);
    }
    out.push(LiveContextWindow {
        hwnd,
        title,
        class_name,
        process_name: lookup_context_process_name(pid),
        rect: (rect.left, rect.top, rect.right, rect.bottom),
    });
    1
}

fn capture_live_context_windows() -> Vec<ContextCapsuleWindow> {
    if cfg!(test) {
        return Vec::new();
    }
    enumerate_live_context_windows()
        .into_iter()
        .map(|window| ContextCapsuleWindow {
            title: window.title,
            class_name: window.class_name,
            process_name: window.process_name,
            rect: window.rect,
            is_maximized: unsafe { IsZoomed(window.hwnd) } != 0,
        })
        .collect()
}

fn context_title_distance(a: &str, b: &str) -> usize {
    if a == b {
        return 0;
    }
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    if left.is_empty() {
        return right.len();
    }
    if right.is_empty() {
        return left.len();
    }
    let mut previous: Vec<usize> = (0..=right.len()).collect();
    let mut current = vec![0usize; right.len() + 1];
    for (left_index, left_ch) in left.iter().enumerate() {
        current[0] = left_index + 1;
        for (right_index, right_ch) in right.iter().enumerate() {
            let cost = usize::from(left_ch != right_ch);
            current[right_index + 1] = (previous[right_index + 1] + 1)
                .min(current[right_index] + 1)
                .min(previous[right_index] + cost);
        }
        std::mem::swap(&mut previous, &mut current);
    }
    previous[right.len()]
}

fn context_titles_similar(left: &str, right: &str) -> bool {
    let left = left.trim().to_lowercase();
    let right = right.trim().to_lowercase();
    if left.is_empty() || right.is_empty() {
        return false;
    }
    left == right
        || left.contains(&right)
        || right.contains(&left)
        || context_title_distance(&left, &right) <= 3
}

fn match_context_window(
    captured: &ContextCapsuleWindow,
    live: &[LiveContextWindow],
) -> Option<HWND> {
    let mut best: Option<(HWND, i32, i64)> = None;
    for window in live {
        let mut score = 0i32;
        if !captured.class_name.is_empty() && captured.class_name == window.class_name {
            score += 2;
        }
        if !captured.process_name.is_empty()
            && captured
                .process_name
                .eq_ignore_ascii_case(window.process_name.as_str())
        {
            score += 2;
        }
        if context_titles_similar(&captured.title, &window.title) {
            score += 1;
        }
        if score < 2 {
            continue;
        }
        let distance = (i64::from(window.rect.0) - i64::from(captured.rect.0)).abs()
            + (i64::from(window.rect.1) - i64::from(captured.rect.1)).abs();
        match best {
            None => best = Some((window.hwnd, score, distance)),
            Some((_, best_score, best_distance))
                if score > best_score || (score == best_score && distance < best_distance) =>
            {
                best = Some((window.hwnd, score, distance));
            }
            _ => {}
        }
    }
    best.map(|(hwnd, _, _)| hwnd)
}

fn restore_captured_context_windows(
    windows: &[ContextCapsuleWindow],
) -> ContextWindowRestoreReport {
    if cfg!(test) {
        return ContextWindowRestoreReport::default();
    }
    let live = enumerate_live_context_windows();
    let mut report = ContextWindowRestoreReport::default();
    for window in windows {
        let Some(hwnd) = match_context_window(window, &live) else {
            report.pending = report.pending.saturating_add(1);
            continue;
        };
        let (left, top, right, bottom) = window.rect;
        let width = (right - left).max(CONTEXT_WINDOW_MIN_SIZE);
        let height = (bottom - top).max(CONTEXT_WINDOW_MIN_SIZE);
        if window.is_maximized {
            unsafe {
                ShowWindow(hwnd, SW_MAXIMIZE);
            }
            report.restored = report.restored.saturating_add(1);
            continue;
        }
        unsafe {
            ShowWindow(hwnd, SW_RESTORE);
        }
        let ok = unsafe {
            SetWindowPos(
                hwnd,
                HWND_TOP,
                left,
                top,
                width,
                height,
                SWP_NOACTIVATE | SWP_NOZORDER,
            )
        };
        if ok == 0 {
            report.errors = report.errors.saturating_add(1);
        } else {
            report.restored = report.restored.saturating_add(1);
        }
    }
    report
}

