const ZONE_CONTEXT_SAVE_SNAPSHOT_ID: usize = 6;
const ZONE_CONTEXT_OPEN_SNAPSHOT_PICKER_ID: usize = 7;
const ZONE_CONTEXT_DELETE_ID: usize = 8;
const ZONE_CONTEXT_BIND_LIVE_FOLDER_ID: usize = 9;
const ZONE_CONTEXT_REFRESH_LIVE_FOLDER_ID: usize = 10;
const ZONE_CONTEXT_UNBIND_LIVE_FOLDER_ID: usize = 11;
