/// Class name + window title for each non-Main `WindowKind`. Returning
/// `&'static [u16]` for both keeps the aux factory allocation-free (§10).
fn aux_class_for(kind: WindowKind) -> &'static [u16] {
    match kind {
        WindowKind::Main => CLASS_NAME,
        WindowKind::IconPicker => AUX_CLASS_ICON_PICKER,
        WindowKind::CapsulePicker => AUX_CLASS_CAPSULE_PICKER,
        WindowKind::ContextMenu => AUX_CLASS_CONTEXT_MENU,
        WindowKind::Tooltip => AUX_CLASS_TOOLTIP,
        WindowKind::DragPreview => AUX_CLASS_DRAG_PREVIEW,
        WindowKind::Settings => AUX_CLASS_SETTINGS,
        WindowKind::About => AUX_CLASS_ABOUT,
        WindowKind::MiniBar => AUX_CLASS_MINIBAR,
        WindowKind::PalettePicker => AUX_CLASS_PALETTE_PICKER,
        WindowKind::RulesWizard => AUX_CLASS_RULES_WIZARD,
        WindowKind::BulkManager => AUX_CLASS_BULK_MANAGER,
        WindowKind::ZoneEditor => AUX_CLASS_ZONE_EDITOR,
        WindowKind::ItemFileRename => AUX_CLASS_ITEM_FILE_RENAME,
        WindowKind::Suggestor => AUX_CLASS_SUGGESTOR,
        WindowKind::Timeline => AUX_CLASS_TIMELINE,
        WindowKind::SnapshotPicker => AUX_CLASS_SNAPSHOT_PICKER,
        WindowKind::Search => AUX_CLASS_SEARCH,
    }
}

