            app.zones
                .add(Zone::new(ZoneId(1), "Anchor", 100, 100, 180, 130));
            app.zones
                .add(Zone::new(ZoneId(2), "Child A", 420, 100, 180, 130));
            app.zones
                .add(Zone::new(ZoneId(3), "Child B", 640, 100, 180, 130));
