    #[test]
    fn active_theme_cycle_reloads_user_theme_dir_before_selecting_next() {
        let root = test_app_root();
        let scratch = scratch_zones_path("active-theme-live-reload");
        let state_dir = scratch.parent().expect("scratch parent");
        std::fs::create_dir_all(state_dir).expect("scratch");
        {
            let mut app = root.app.borrow_mut();
            app.zones_path = scratch.clone();
        }
        let initial_options = load_available_theme_options(&root).expect("load initial themes");
        assert!(root.app.borrow().set_available_themes(initial_options));
        assert!(
            apply_active_theme_to_app(&root, SmolStr::new_static("forest-green"))
                .expect("apply forest")
        );

        let themes_dir = state_dir.join("themes");
        std::fs::create_dir_all(&themes_dir).expect("themes dir");
        std::fs::write(
            themes_dir.join("live-cyan.json"),
            r##"{
  "id": "live-cyan",
  "name": "Live Cyan",
  "is_builtin": false,
  "colors": {
    "accent": "#22d3ee",
    "background": "rgba(8, 47, 73, 0.75)",
    "text": "#ecfeff",
    "border": "rgba(34, 211, 238, 0.22)"
  },
  "capsule": {
    "shape": "rounded",
    "size": "medium",
    "blur_radius": 18.0
  },
  "animation": {
    "expand_duration_ms": 210,
    "collapse_duration_ms": 170
  },
  "glassmorphism": {
    "blur": 18.0,
    "opacity": 0.78,
    "saturation": 1.35
  }
}"##,
        )
        .expect("theme");

        queue_active_theme_cycle(&root, std::ptr::null_mut());
        let mut drained = smallvec::SmallVec::<[Command; 8]>::new();
        assert_eq!(root.dispatcher.drain_into(&mut drained), 1);
        assert!(matches!(
            drained.first(),
            Some(Command::SetActiveTheme(theme_id)) if theme_id.as_str() == "live-cyan"
        ));
        assert!(
            root.app
                .borrow()
                .available_themes
                .borrow()
                .iter()
                .any(|theme| theme.id.as_str() == "live-cyan")
        );

        let _ = std::fs::remove_dir_all(state_dir);
    }

